window.C3KO_DATA = {"version":1,"levels":[{"id":"A1","name":["Beginner","Pemula"],"goal":["Introduce yourself, talk about daily life, ask and answer simple questions.","Memperkenalkan diri, membicarakan kehidupan sehari-hari, bertanya dan menjawab hal sederhana."],"topics":[{"id":"a1-alphabet","title":["Alphabet, pronunciation & written accents","Alfabet, pelafalan & tanda aksen"],"what":["Spanish is spelled almost exactly as it is pronounced. A few letters change their sound depending on the next vowel (c, g), h is always silent, and ñ is a separate letter. Stress follows simple rules; a written accent (´) marks every exception.","Bahasa Spanyol ditulis hampir persis seperti diucapkan. Beberapa huruf berubah bunyi tergantung vokal berikutnya (c, g), h selalu tidak dibaca, dan ñ adalah huruf tersendiri. Tekanan kata mengikuti aturan sederhana; tanda aksen (´) menandai setiap pengecualian."],"pattern":[{"title":["Letters that change","Huruf yang berubah bunyi"],"head":[["Spelling","Ejaan"],["Sound","Bunyi"],["Example","Contoh"]],"rows":[["{c} + a, o, u",["k","k"],"casa, cosa, Cuba"],["{c} + e, i",["th (Spain) / s (Latin America)","th (Spanyol) / s (Amerika Latin)"],"cena, cine"],["{g} + e, i  ·  {j}",["strong h (throat)","h kuat (tenggorokan)"],"gente, jamón"],["{gu} + e, i",["hard g (u silent)","g keras (u tidak dibaca)"],"guerra, guitarra"],["{qu} + e, i",["k (u silent)","k (u tidak dibaca)"],"queso, quince"],["{h}",["silent","tidak dibaca"],"hola, hotel"],["{ll}  ·  {y}",["like y in 'yes'","seperti y dalam 'ya'"],"llamar, yo"],["{ñ}",["ny","ny"],"España, mañana"],["{rr}  ·  r- at the start",["rolled r","r getar panjang"],"perro, rojo"],["{v} = {b}",["the same sound","bunyinya sama"],"vino, bien"],["{z}",["th (Spain) / s (Latin America)","th (Spanyol) / s (Amerika Latin)"],"zapato"]]},{"title":["Where the stress falls","Letak tekanan kata"],"head":[["Word ends in…","Kata berakhiran…"],["Stress","Tekanan"],["Examples","Contoh"]],"rows":[[["a vowel, -n or -s","vokal, -n atau -s"],["second-to-last syllable","suku kata kedua dari belakang"],"ca{sa}, ha{blan}, li{bros}"],[["any other consonant","konsonan lain"],["last syllable","suku kata terakhir"],"ha{blar}, ciu{dad}, espa{ñol}"],[["exception to these rules","pengecualian aturan ini"],["written accent shows it","ditunjukkan tanda aksen"],"ca{fé}, ár{bol}, {mú}sica, ca{mión}"]],"note":["Some one-syllable words carry an accent only to tell them apart: tú (you) / tu (your), él (he) / el (the), sí (yes) / si (if), más (more) / mas (but).","Beberapa kata satu suku kata diberi aksen hanya untuk membedakan: tú (kamu) / tu (-mu), él (dia) / el (artikel), sí (ya) / si (jika), más (lebih) / mas (tetapi)."]}],"examples":[["¿Cómo te llamas? — Me llamo Lucía.",["What's your name? — My name is Lucía.","Siapa namamu? — Nama saya Lucía."]],["Hola, ¿qué tal?",["Hi, how are you?","Halo, apa kabar?"]],["¡Buenos días! Mucho gusto.",["Good morning! Nice to meet you.","Selamat pagi! Senang berkenalan."]]],"tip":["Questions and exclamations open with an upside-down mark: ¿…? and ¡…!. The opening mark goes where the question actually starts: Y tú, ¿de dónde eres?","Pertanyaan dan seruan dibuka dengan tanda terbalik: ¿…? dan ¡…!. Tanda pembuka diletakkan di awal bagian yang benar-benar bertanya: Y tú, ¿de dónde eres?"]},{"id":"a1-pronouns","title":["Subject pronouns & tú vs usted","Kata ganti subjek & tú vs usted"],"what":["Spanish has an informal 'you' (tú, vosotros) and a polite 'you' (usted, ustedes). Usted takes the same verb form as él/ella. Because the verb ending already shows the person, subject pronouns are usually left out and used only for emphasis or contrast.","Bahasa Spanyol punya 'kamu' informal (tú, vosotros) dan 'Anda' sopan (usted, ustedes). Usted memakai bentuk kata kerja yang sama dengan él/ella. Karena akhiran kata kerja sudah menunjukkan pelaku, kata ganti subjek biasanya dihilangkan dan hanya dipakai untuk penekanan atau kontras."],"pattern":[{"head":[["Person","Persona"],["Singular","Tunggal"],["Plural","Jamak"]],"rows":[["1","{yo}","{nosotros} / {nosotras}"],[["2 informal","2 informal"],"{tú}",["{vosotros} / {vosotras} (Spain only)","{vosotros} / {vosotras} (hanya Spanyol)"]],[["2 polite","2 sopan"],"{usted} (Ud.)","{ustedes} (Uds.)"],["3","{él} / {ella}","{ellos} / {ellas}"]],"note":["In Latin America ustedes is used for every 'you all', friendly or polite. The masculine plural (nosotros, ellos) covers mixed groups.","Di Amerika Latin ustedes dipakai untuk semua 'kalian', akrab maupun sopan. Bentuk jamak maskulin (nosotros, ellos) dipakai untuk kelompok campuran."]}],"examples":[["Soy Carlos. ¿Y tú?",["I'm Carlos. And you?","Saya Carlos. Dan kamu?"]],["¿Usted habla inglés?",["Do you (polite) speak English?","Apakah Anda bisa berbahasa Inggris?"]],["Ella trabaja, pero él no.",["She works, but he doesn't.","Dia (perempuan) bekerja, tetapi dia (laki-laki) tidak."]]],"tip":["Use usted with strangers, older people and in formal situations; tú with friends, family and children. If someone says '¿Nos tuteamos?', they are offering to switch to tú.","Pakai usted dengan orang asing, orang yang lebih tua dan dalam situasi resmi; tú dengan teman, keluarga dan anak-anak. Jika seseorang berkata '¿Nos tuteamos?', ia menawarkan untuk beralih ke tú."]},{"id":"a1-nouns","title":["Nouns: gender, articles & plurals","Kata benda: gender, artikel & jamak"],"what":["Every noun is masculine or feminine, and the article shows which: el/un (masculine), la/una (feminine). Most nouns in -o are masculine and most in -a are feminine, but there are exceptions to learn. Plurals add -s after a vowel and -es after a consonant.","Setiap kata benda bergender maskulin atau feminin, dan artikelnya menunjukkan gendernya: el/un (maskulin), la/una (feminin). Kebanyakan kata benda berakhiran -o maskulin dan berakhiran -a feminin, tetapi ada pengecualian yang perlu dihafal. Jamak ditambah -s setelah vokal dan -es setelah konsonan."],"pattern":[{"title":["Articles","Artikel"],"head":["",["Definite (the)","Takrif (the)"],["Indefinite (a / some)","Taktakrif (a / beberapa)"]],"rows":[[["masculine singular","maskulin tunggal"],"{el} libro","{un} libro"],[["feminine singular","feminin tunggal"],"{la} casa","{una} casa"],[["masculine plural","maskulin jamak"],"{los} libros","{unos} libros"],[["feminine plural","feminin jamak"],"{las} casas","{unas} casas"]]},{"title":["Gender clues and plurals","Petunjuk gender dan jamak"],"head":[["Ending","Akhiran"],["Gender","Gender"],["Examples","Contoh"]],"rows":[["-o",["masculine","maskulin"],"el niñ{o}, el vas{o} (but: la mano, la foto, la radio)"],["-a",["feminine","feminin"],"la mes{a}, la cas{a} (but: el día, el mapa)"],["-ma (Greek origin)",["masculine","maskulin"],"el proble{ma}, el idio{ma}, el siste{ma}"],["-ción, -sión, -dad, -tad",["feminine","feminin"],"la esta{ción}, la ciu{dad}, la liber{tad}"],[["plural after a vowel","jamak setelah vokal"],"+ s","casa{s}, café{s}"],[["plural after a consonant","jamak setelah konsonan"],"+ es","ciudad{es}, papel{es}; lápiz → lápi{ces}"]],"note":["Feminine nouns starting with a stressed a- take el in the singular for sound: el agua, el águila — but las aguas, and the noun stays feminine (el agua fría).","Kata benda feminin yang diawali a- bertekanan memakai el dalam bentuk tunggal demi bunyi: el agua, el águila — tetapi las aguas, dan katanya tetap feminin (el agua fría)."]}],"examples":[["el día y la noche",["the day and the night","siang dan malam"]],["Tengo un problema.",["I have a problem.","Saya punya masalah."]],["Las ciudades son grandes.",["The cities are big.","Kota-kotanya besar."]]],"tip":["Learn every noun together with its article (la mano, el día), not alone. Guessing the gender from the ending works most of the time, but the common exceptions are exactly the words you use every day.","Hafalkan setiap kata benda bersama artikelnya (la mano, el día), jangan sendirian. Menebak gender dari akhiran biasanya berhasil, tetapi pengecualian yang umum justru kata-kata yang dipakai setiap hari."]},{"id":"a1-adjectives","title":["Adjectives: agreement & position","Kata sifat: kesesuaian & posisi"],"what":["Adjectives agree with their noun in gender and number. Adjectives in -o have four forms; those in -e or a consonant have only singular and plural. Most adjectives come after the noun.","Kata sifat menyesuaikan gender dan jumlah kata bendanya. Kata sifat berakhiran -o punya empat bentuk; yang berakhiran -e atau konsonan hanya punya bentuk tunggal dan jamak. Kebanyakan kata sifat diletakkan setelah kata benda."],"pattern":[{"head":[["Type","Jenis"],["masc. sg.","mask. tg."],["fem. sg.","fem. tg."],["masc. pl.","mask. jm."],["fem. pl.","fem. jm."]],"rows":[["-o","alt{o}","alt{a}","alt{os}","alt{as}"],["-e","grand{e}","grand{e}","grand{es}","grand{es}"],[["consonant","konsonan"],"azul","azul","azul{es}","azul{es}"],[["nationality in consonant","kebangsaan berakhiran konsonan"],"español","español{a}","español{es}","español{as}"]],"note":["bueno and malo lose -o before a masculine singular noun: un buen día, un mal momento. grande becomes gran before any singular noun and then means 'great': una gran ciudad.","bueno dan malo kehilangan -o sebelum kata benda maskulin tunggal: un buen día, un mal momento. grande menjadi gran sebelum kata benda tunggal dan berarti 'hebat': una gran ciudad."]}],"examples":[["una casa blanca",["a white house","rumah putih"]],["Los chicos son simpáticos.",["The boys are friendly.","Anak-anak laki-laki itu ramah."]],["Es un buen libro.",["It's a good book.","Itu buku yang bagus."]]],"tip":["Check the noun, not the speaker: Lucía has 'un coche rojo' (coche is masculine), even though Lucía is a woman.","Lihat kata bendanya, bukan pembicaranya: Lucía punya 'un coche rojo' (coche maskulin), meskipun Lucía perempuan."]},{"id":"a1-ser","title":["Ser (to be): identity and description","Ser (adalah): identitas dan deskripsi"],"what":["Spanish has two verbs for 'to be'. Ser says what someone or something is: name, nationality, origin, job, relationship, permanent characteristics, time and date, and what something is made of.","Bahasa Spanyol punya dua kata kerja untuk 'adalah/berada'. Ser menyatakan siapa atau apa sesuatu itu: nama, kebangsaan, asal, pekerjaan, hubungan, ciri tetap, jam dan tanggal, serta bahan sesuatu."],"pattern":[{"head":[["Person","Persona"],["ser","ser"],["Use","Pemakaian"],["Example","Contoh"]],"rows":[["yo","{soy}",["identity","identitas"],"Soy Lucía."],["tú","{eres}",["origin","asal"],"¿Eres de México?"],["él / ella / usted","{es}",["job","pekerjaan"],"Es médica."],["nosotros","{somos}",["nationality","kebangsaan"],"Somos españoles."],["vosotros","{sois}",["characteristics","ciri"],"Sois muy altos."],["ellos / ustedes","{son}",["time","waktu"],"Son las tres."]]}],"examples":[["Carlos es profesor.",["Carlos is a teacher.","Carlos seorang guru."]],["La mesa es de madera.",["The table is made of wood.","Meja itu terbuat dari kayu."]],["Hoy es lunes.",["Today is Monday.","Hari ini hari Senin."]]],"tip":["No article before a job after ser: 'Es médica', not 'Es una médica' — unless you add an adjective: 'Es una médica excelente'.","Tanpa artikel sebelum pekerjaan setelah ser: 'Es médica', bukan 'Es una médica' — kecuali ditambah kata sifat: 'Es una médica excelente'."]},{"id":"a1-estar","title":["Estar (to be): location and states","Estar (berada/sedang): lokasi dan keadaan"],"what":["Estar says where something is and how someone or something is right now: mood, health, temporary state, result of a change. It is also used with the gerund for actions in progress (estoy comiendo).","Estar menyatakan di mana sesuatu berada dan bagaimana keadaan seseorang atau sesuatu saat ini: suasana hati, kesehatan, keadaan sementara, hasil sebuah perubahan. Estar juga dipakai dengan gerundio untuk tindakan yang sedang berlangsung (estoy comiendo)."],"pattern":[{"head":[["Person","Persona"],["estar","estar"],["Use","Pemakaian"],["Example","Contoh"]],"rows":[["yo","{estoy}",["mood","suasana hati"],"Estoy contento."],["tú","{estás}",["health","kesehatan"],"¿Estás bien?"],["él / ella / usted","{está}",["location","lokasi"],"Madrid está en España."],["nosotros","{estamos}",["temporary state","keadaan sementara"],"Estamos cansados."],["vosotros","{estáis}",["result of a change","hasil perubahan"],"La puerta está abierta."],["ellos / ustedes","{están}",["location","lokasi"],"Los niños están en casa."]]}],"examples":[["¿Dónde está el baño?",["Where is the bathroom?","Di mana kamar mandinya?"]],["La sopa está fría.",["The soup is cold.","Supnya dingin."]],["Estoy en el trabajo.",["I'm at work.","Saya sedang di tempat kerja."]]],"tip":["Location of things and people always takes estar, even permanent places: 'Lima está en Perú'. Only events use ser for location: 'La fiesta es en mi casa'.","Lokasi benda dan orang selalu memakai estar, bahkan tempat yang tetap: 'Lima está en Perú'. Hanya acara/peristiwa yang memakai ser untuk lokasi: 'La fiesta es en mi casa'."]},{"id":"a1-hay","title":["Hay (there is / there are)","Hay (ada)"],"what":["Hay says that something exists or can be found somewhere. It never changes for singular or plural. Use hay with a/some/numbers or no article; use está/están for specific things with el/la/los/las, names or possessives.","Hay menyatakan bahwa sesuatu ada atau bisa ditemukan di suatu tempat. Bentuknya tidak pernah berubah untuk tunggal maupun jamak. Pakai hay dengan un/una, angka, atau tanpa artikel; pakai está/están untuk benda tertentu dengan el/la/los/las, nama atau kata kepemilikan."],"pattern":[{"head":[["Use","Pemakaian"],["Form","Bentuk"],["Example","Contoh"]],"rows":[[["exists (new information)","keberadaan (info baru)"],"{hay} + un/una/unos/número/—","{Hay} un banco aquí. {Hay} tres sillas. {Hay} leche."],[["where a specific thing is","letak benda tertentu"],"el/la/mi… + {está/están}","El banco {está} aquí. Mis llaves {están} en la mesa."],[["negative","negatif"],"no {hay} + (noun without article)","No {hay} pan. No {hay} problema."],[["question","pertanyaan"],"¿{Hay}…?","¿{Hay} una farmacia cerca?"]]}],"examples":[["En mi calle hay dos restaurantes.",["There are two restaurants on my street.","Di jalan saya ada dua restoran."]],["¿Hay wifi en el hotel?",["Is there wifi in the hotel?","Apakah ada wifi di hotel?"]],["El museo está en el centro.",["The museum is in the centre.","Museum itu ada di pusat kota."]]],"tip":["Never say 'hay el…' or 'hayn': hay has one form only, and a specific thing with el/la takes está.","Jangan pernah mengatakan 'hay el…' atau 'hayn': hay hanya punya satu bentuk, dan benda tertentu dengan el/la memakai está."]},{"id":"a1-present-regular","title":["Present tense: regular verbs","Kala kini: kata kerja beraturan"],"what":["Verbs are grouped by their infinitive ending: -ar, -er, -ir. Remove the ending and add the present endings. -er and -ir share all endings except nosotros and vosotros. The present covers 'I work', 'I'm working' and fixed plans ('mañana trabajo').","Kata kerja dikelompokkan menurut akhiran infinitifnya: -ar, -er, -ir. Buang akhirannya lalu tambahkan akhiran kala kini. -er dan -ir memakai akhiran yang sama kecuali untuk nosotros dan vosotros. Kala kini mencakup 'saya bekerja', 'saya sedang bekerja' dan rencana pasti ('mañana trabajo')."],"pattern":[{"head":[["Person","Persona"],"hablar","comer","vivir"],"rows":[["yo","habl{o}","com{o}","viv{o}"],["tú","habl{as}","com{es}","viv{es}"],["él / ella / usted","habl{a}","com{e}","viv{e}"],["nosotros","habl{amos}","com{emos}","viv{imos}"],["vosotros","habl{áis}","com{éis}","viv{ís}"],["ellos / ustedes","habl{an}","com{en}","viv{en}"]]}],"examples":[["Hablo español y un poco de francés.",["I speak Spanish and a little French.","Saya bisa bahasa Spanyol dan sedikit bahasa Prancis."]],["¿Dónde vives?",["Where do you live?","Kamu tinggal di mana?"]],["Comemos a las dos.",["We eat at two.","Kami makan pukul dua."]]],"tip":["The stress in the present is on the stem except in nosotros and vosotros: HA-blo, HA-blan but ha-BLA-mos. 'Hablo' (I speak) and 'habló' (he spoke) differ only in stress.","Tekanan kala kini ada pada akar kata kecuali untuk nosotros dan vosotros: HA-blo, HA-blan tetapi ha-BLA-mos. 'Hablo' (saya berbicara) dan 'habló' (dia berbicara, lampau) hanya berbeda tekanan."]},{"id":"a1-present-stem","title":["Present tense: stem-changing verbs","Kala kini: kata kerja dengan perubahan akar"],"what":["In many common verbs the stressed vowel of the stem changes: e → ie, o → ue, e → i (only -ir verbs). The change happens in every form except nosotros and vosotros, where the stem is not stressed. The endings stay regular.","Pada banyak kata kerja umum, vokal akar yang bertekanan berubah: e → ie, o → ue, e → i (hanya kata kerja -ir). Perubahan terjadi di semua bentuk kecuali nosotros dan vosotros, karena di sana akarnya tidak bertekanan. Akhirannya tetap beraturan."],"pattern":[{"head":[["Person","Persona"],"querer (e → ie)","poder (o → ue)","pedir (e → i)"],"rows":[["yo","qu{ie}ro","p{ue}do","p{i}do"],["tú","qu{ie}res","p{ue}des","p{i}des"],["él / ella / usted","qu{ie}re","p{ue}de","p{i}de"],["nosotros","queremos","podemos","pedimos"],["vosotros","queréis","podéis","pedís"],["ellos / ustedes","qu{ie}ren","p{ue}den","p{i}den"]],"note":["Also e → ie: pensar, empezar, cerrar, entender, preferir, sentir. o → ue: dormir, volver, contar, encontrar, costar. e → i: repetir, servir, seguir. jugar changes u → ue: juego, juegas.","Juga e → ie: pensar, empezar, cerrar, entender, preferir, sentir. o → ue: dormir, volver, contar, encontrar, costar. e → i: repetir, servir, seguir. jugar berubah u → ue: juego, juegas."]}],"examples":[["¿Puedes repetir, por favor?",["Can you repeat, please?","Bisa diulang, tolong?"]],["Duermo ocho horas.",["I sleep eight hours.","Saya tidur delapan jam."]],["Queremos un café.",["We want a coffee.","Kami mau kopi."]]],"tip":["Think of it as a 'boot': the forms yo, tú, él and ellos (the outline of a boot in the table) change; nosotros and vosotros stay outside the boot.","Bayangkan bentuk 'sepatu bot': bentuk yo, tú, él dan ellos (garis sepatu bot di tabel) berubah; nosotros dan vosotros tetap di luar sepatu."]},{"id":"a1-present-irregular","title":["Present tense: irregular yo forms and ir","Kala kini: bentuk yo tidak beraturan dan ir"],"what":["Some very common verbs are irregular only in the yo form, often adding -g- or -zc-. A few are irregular throughout, above all ir (to go). The other forms usually follow the regular pattern.","Beberapa kata kerja yang sangat umum hanya tidak beraturan pada bentuk yo, sering dengan tambahan -g- atau -zc-. Beberapa lainnya tidak beraturan di semua bentuk, terutama ir (pergi). Bentuk lainnya biasanya mengikuti pola beraturan."],"pattern":[{"title":["Irregular yo only","Hanya yo yang tidak beraturan"],"head":[["Infinitive","Infinitif"],"yo","tú",["Meaning","Arti"]],"rows":[["hacer","ha{go}","haces",["do, make","melakukan, membuat"]],["poner","pon{go}","pones",["put","menaruh"]],["salir","sal{go}","sales",["go out, leave","keluar, berangkat"]],["traer","trai{go}","traes",["bring","membawa"]],["conocer","cono{zco}","conoces",["know (people, places)","mengenal (orang, tempat)"]],["saber","{sé}","sabes",["know (facts)","tahu (fakta)"]],["ver","{veo}","ves",["see","melihat"]],["dar","{doy}","das",["give","memberi"]]]},{"title":["Fully irregular","Tidak beraturan sepenuhnya"],"head":[["Person","Persona"],"ir","venir","decir"],"rows":[["yo","{voy}","{vengo}","{digo}"],["tú","{vas}","{vienes}","{dices}"],["él / ella / usted","{va}","{viene}","{dice}"],["nosotros","{vamos}","venimos","decimos"],["vosotros","{vais}","venís","decís"],["ellos / ustedes","{van}","{vienen}","{dicen}"]]}],"examples":[["Voy al trabajo en metro.",["I go to work by metro.","Saya pergi ke kantor naik metro."]],["Salgo de casa a las ocho.",["I leave home at eight.","Saya keluar rumah pukul delapan."]],["No sé dónde está.",["I don't know where it is.","Saya tidak tahu di mana itu."]]],"tip":["saber = know a fact or how to do something (sé nadar); conocer = be familiar with a person or place (conozco Madrid). A person as object takes 'a': Conozco a Carlos.","saber = tahu fakta atau bisa melakukan sesuatu (sé nadar); conocer = mengenal orang atau tempat (conozco Madrid). Orang sebagai objek memakai 'a': Conozco a Carlos."]},{"id":"a1-tener","title":["Tener (to have) and its expressions","Tener (punya) dan ungkapannya"],"what":["Tener means 'to have' and is irregular (tengo, tienes…). Spanish uses tener where English uses 'be' for age and physical feelings: tengo 20 años, tengo hambre. Tener que + infinitive means 'have to'.","Tener berarti 'punya' dan tidak beraturan (tengo, tienes…). Bahasa Spanyol memakai tener untuk umur dan perasaan fisik: tengo 20 años (umur saya 20 tahun), tengo hambre (saya lapar). Tener que + infinitif berarti 'harus'."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"tener"],"rows":[["yo","{tengo}"],["tú","{tienes}"],["él / ella / usted","{tiene}"],["nosotros","tenemos"],["vosotros","tenéis"],["ellos / ustedes","{tienen}"]]},{"title":["Expressions","Ungkapan"],"head":[["Spanish","Spanyol"],["Meaning","Arti"]],"rows":[["tener … {años}",["be … years old","berumur … tahun"]],["tener {hambre} / {sed}",["be hungry / thirsty","lapar / haus"]],["tener {frío} / {calor}",["be cold / hot (person)","kedinginan / kepanasan (orang)"]],["tener {sueño} / {miedo}",["be sleepy / afraid","mengantuk / takut"]],["tener {razón} / {prisa}",["be right / in a hurry","benar / terburu-buru"]],["tener {que} + infinitive",["have to","harus"]]]}],"examples":[["Tengo veinticinco años.",["I'm twenty-five.","Umur saya dua puluh lima tahun."]],["¿Tienes hambre?",["Are you hungry?","Kamu lapar?"]],["Tenemos que trabajar mañana.",["We have to work tomorrow.","Kami harus bekerja besok."]]],"tip":["hambre, sed, frío, calor are nouns, so 'very' is mucho/mucha, not muy: tengo mucha hambre, tengo mucho frío.","hambre, sed, frío, calor adalah kata benda, jadi 'sangat' memakai mucho/mucha, bukan muy: tengo mucha hambre, tengo mucho frío."]},{"id":"a1-questions","title":["Questions & negation","Kalimat tanya & negasi"],"what":["For a yes/no question, keep the word order and raise your voice, or put the subject after the verb. Question words always carry a written accent. To make a sentence negative, put no directly before the verb.","Untuk pertanyaan ya/tidak, susunan kata tetap dan intonasi naik, atau subjek diletakkan setelah kata kerja. Kata tanya selalu memakai tanda aksen. Untuk kalimat negatif, letakkan no tepat sebelum kata kerja."],"pattern":[{"title":["Question words","Kata tanya"],"head":[["Spanish","Spanyol"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{qué}",["what","apa"],"¿Qué quieres?"],["{quién} / {quiénes}",["who","siapa"],"¿Quién es?"],["{dónde} / {adónde}",["where / where to","di mana / ke mana"],"¿Adónde vas?"],["{cuándo}",["when","kapan"],"¿Cuándo llegas?"],["{cómo}",["how","bagaimana"],"¿Cómo estás?"],["{por qué}",["why","mengapa"],"¿Por qué no vienes?"],["{cuál} / {cuáles}",["which (one)","yang mana"],"¿Cuál es tu número?"],["{cuánto/a/os/as}",["how much / many","berapa"],"¿Cuántos años tienes?"]]},{"title":["Negation","Negasi"],"head":[["Pattern","Pola"],["Example","Contoh"]],"rows":[["{no} + verb","{No} hablo alemán."],["{no} + pronoun + verb","{No} lo sé."],["{no} + verb + {nada / nunca / nadie}","{No} quiero {nada}."]]}],"examples":[["¿De dónde eres?",["Where are you from?","Kamu berasal dari mana?"]],["¿Cuánto cuesta?",["How much is it?","Berapa harganya?"]],["No tengo coche.",["I don't have a car.","Saya tidak punya mobil."]]],"tip":["Prepositions go at the front of the question, never at the end: ¿De dónde eres? (lit. 'from where are you?'), ¿Con quién vives?","Kata depan diletakkan di awal pertanyaan, tidak pernah di akhir: ¿De dónde eres?, ¿Con quién vives?"]},{"id":"a1-possessives","title":["Possessive adjectives","Kata sifat kepemilikan"],"what":["Possessives come before the noun and agree with the thing owned, not with the owner. mi, tu, su only add -s in the plural; nuestro and vuestro also change for gender. Su can mean his, her, its, their or your (usted/ustedes).","Kata kepemilikan diletakkan sebelum kata benda dan menyesuaikan benda yang dimiliki, bukan pemiliknya. mi, tu, su hanya ditambah -s untuk jamak; nuestro dan vuestro juga berubah menurut gender. Su bisa berarti miliknya (dia), milik mereka, atau milik Anda (usted/ustedes)."],"pattern":[{"head":[["Owner","Pemilik"],["one thing","satu benda"],["several things","beberapa benda"]],"rows":[["yo","{mi} libro / {mi} casa","{mis} libros / {mis} casas"],["tú","{tu} libro","{tus} libros"],["él / ella / usted","{su} libro","{sus} libros"],["nosotros","{nuestro} libro / {nuestra} casa","{nuestros} libros / {nuestras} casas"],["vosotros","{vuestro} libro / {vuestra} casa","{vuestros} libros / {vuestras} casas"],["ellos / ustedes","{su} libro","{sus} libros"]]}],"examples":[["Mi hermana vive en Sevilla.",["My sister lives in Seville.","Kakak/adik perempuan saya tinggal di Sevilla."]],["Nuestra casa es pequeña.",["Our house is small.","Rumah kami kecil."]],["¿Son sus hijos?",["Are they his/her/your children?","Apakah mereka anak-anaknya / anak-anak Anda?"]]],"tip":["Tu (your) has no accent; tú (you) has one. If su is unclear, say it another way: el libro de él, el libro de ella, el libro de usted.","Tu (-mu) tanpa aksen; tú (kamu) dengan aksen. Jika su kurang jelas, ungkapkan dengan cara lain: el libro de él, el libro de ella, el libro de usted."]},{"id":"a1-demonstratives","title":["Demonstratives: este, ese, aquel","Kata tunjuk: este, ese, aquel"],"what":["Spanish has three distances: este (this, near me), ese (that, near you or not far), aquel (that over there, far from both). They agree with the noun. Esto, eso, aquello are neutral and refer to an idea or an unknown thing.","Bahasa Spanyol punya tiga jarak: este (ini, dekat saya), ese (itu, dekat kamu atau tidak jauh), aquel (itu di sana, jauh dari keduanya). Kata tunjuk menyesuaikan kata bendanya. Esto, eso, aquello netral dan merujuk pada gagasan atau benda yang belum diketahui."],"pattern":[{"head":["",["near me","dekat saya"],["near you","dekat kamu"],["far","jauh"]],"rows":[[["masculine singular","maskulin tunggal"],"{este}","{ese}","{aquel}"],[["feminine singular","feminin tunggal"],"{esta}","{esa}","{aquella}"],[["masculine plural","maskulin jamak"],"{estos}","{esos}","{aquellos}"],[["feminine plural","feminin jamak"],"{estas}","{esas}","{aquellas}"],[["neutral","netral"],"{esto}","{eso}","{aquello}"]]}],"examples":[["Este café está muy rico.",["This coffee is very tasty.","Kopi ini enak sekali."]],["¿Qué es eso?",["What's that?","Apa itu?"]],["Aquella montaña es muy alta.",["That mountain over there is very high.","Gunung di sana itu sangat tinggi."]]],"tip":["Este has no -o in the masculine singular: este libro, never 'esto libro'. Esto is only used alone, without a noun.","Este tidak berakhiran -o untuk maskulin tunggal: este libro, bukan 'esto libro'. Esto hanya dipakai sendiri, tanpa kata benda."]},{"id":"a1-gustar","title":["Gustar (to like)","Gustar (suka)"],"what":["Gustar works backwards compared with English 'like': the thing liked is the subject and the person is an indirect object (me, te, le…). So the verb is gusta for one thing or an infinitive, and gustan for plural things.","Gustar bekerja terbalik dibanding 'like' dalam bahasa Inggris: hal yang disukai menjadi subjek, dan orangnya menjadi objek tak langsung (me, te, le…). Jadi kata kerjanya gusta untuk satu hal atau infinitif, dan gustan untuk benda jamak."],"pattern":[{"head":[["(emphasis)","(penekanan)"],["Pronoun","Kata ganti"],["one thing / verb","satu hal / kata kerja"],["plural things","benda jamak"]],"rows":[["(a mí)","{me}","gusta el café","gust{an} los perros"],["(a ti)","{te}","gusta bailar","gust{an} las fiestas"],["(a él / ella / usted)","{le}","gusta la música","gust{an} los libros"],["(a nosotros)","{nos}","gusta viajar","gust{an} las playas"],["(a vosotros)","{os}","gusta el cine","gust{an} los deportes"],["(a ellos / ustedes)","{les}","gusta España","gust{an} los gatos"]],"note":["The same pattern: encantar (love), interesar (interest). Agreement: '¿Te gusta?' — 'A mí también / A mí tampoco'.","Pola yang sama: encantar (sangat suka), interesar (tertarik). Menyetujui: '¿Te gusta?' — 'A mí también / A mí tampoco'."]}],"examples":[["Me gusta el chocolate.",["I like chocolate.","Saya suka cokelat."]],["Nos gustan las películas españolas.",["We like Spanish films.","Kami suka film Spanyol."]],["A Carlos le encanta cocinar.",["Carlos loves cooking.","Carlos sangat suka memasak."]]],"tip":["Never 'yo gusto' for 'I like': that means 'I am pleasing'. Use 'me gusta'. With a name, keep le: A Lucía le gusta…","Jangan mengatakan 'yo gusto' untuk 'saya suka': artinya 'saya menyenangkan'. Pakai 'me gusta'. Dengan nama, tetap pakai le: A Lucía le gusta…"]},{"id":"a1-numbers-time","title":["Numbers, prices & telling the time","Angka, harga & menyebut jam"],"what":["Numbers 16–29 are written as one word (dieciséis, veintiuno); from 31 they use y (treinta y uno). Uno becomes un before a masculine noun and una before a feminine one. For the time use ser + la/las + hour.","Angka 16–29 ditulis sebagai satu kata (dieciséis, veintiuno); mulai 31 memakai y (treinta y uno). Uno menjadi un sebelum kata benda maskulin dan una sebelum kata benda feminin. Untuk jam pakai ser + la/las + jam."],"pattern":[{"title":["Numbers","Angka"],"head":["","","",""],"rows":[["1 uno","6 seis","11 once","16 {dieci}séis"],["2 dos","7 siete","12 doce","20 veinte · 21 {veinti}uno"],["3 tres","8 ocho","13 trece","30 treinta · 31 treinta {y} uno"],["4 cuatro","9 nueve","14 catorce","40 cuarenta · 50 cincuenta"],["5 cinco","10 diez","15 quince","100 {cien} · 101 {ciento} uno"]]},{"title":["Telling the time","Menyebut jam"],"head":[["Time","Jam"],["Spanish","Spanyol"]],"rows":[["1:00","Es {la} una."],["3:00","Son {las} tres."],["3:15","Son las tres {y cuarto}."],["3:30","Son las tres {y media}."],["3:45","Son las cuatro {menos cuarto}."],["3:50","Son las cuatro {menos diez}."],[["at 3:00","pukul 3:00"],"{a las} tres"]]}],"examples":[["¿Qué hora es? — Son las dos y media.",["What time is it? — It's half past two.","Jam berapa? — Pukul setengah tiga."]],["La clase empieza a las nueve.",["The class starts at nine.","Kelasnya mulai pukul sembilan."]],["Son veintiún euros.",["It's twenty-one euros.","Harganya dua puluh satu euro."]]],"tip":["'It's one o'clock' is singular: es la una; every other hour is plural: son las dos. For 'at', use a: a la una, a las ocho.","'Pukul satu' tunggal: es la una; jam lain jamak: son las dos. Untuk 'pada pukul', pakai a: a la una, a las ocho."]},{"id":"a1-ir-a","title":["Near future: ir a + infinitive","Masa depan dekat: ir a + infinitif"],"what":["Ir (in the present) + a + infinitive talks about plans and things that are about to happen, like 'going to' in English. It is the most common way to talk about the future in everyday speech.","Ir (kala kini) + a + infinitif menyatakan rencana dan hal yang akan segera terjadi, seperti 'going to' dalam bahasa Inggris. Ini cara paling umum untuk membicarakan masa depan dalam percakapan sehari-hari."],"pattern":[{"head":[["Person","Persona"],["ir","ir"],"",["infinitive","infinitif"]],"rows":[["yo","{voy}","{a}","comer"],["tú","{vas}","{a}","estudiar"],["él / ella / usted","{va}","{a}","llover"],["nosotros","{vamos}","{a}","salir"],["vosotros","{vais}","{a}","viajar"],["ellos / ustedes","{van}","{a}","trabajar"]],"note":["Time words that go with it: hoy, esta noche, mañana, el lunes, la semana que viene, el próximo año.","Kata waktu yang sering menyertainya: hoy, esta noche, mañana, el lunes, la semana que viene, el próximo año."]}],"examples":[["Voy a estudiar esta noche.",["I'm going to study tonight.","Saya akan belajar malam ini."]],["Va a llover.",["It's going to rain.","Akan turun hujan."]],["¿Qué vais a hacer el sábado?",["What are you (all) going to do on Saturday?","Apa yang akan kalian lakukan hari Sabtu?"]]],"tip":["Don't forget the a: 'Voy a comer', not 'Voy comer'. 'Vamos a…' alone can also mean 'Let's…': ¡Vamos a bailar!","Jangan lupa a: 'Voy a comer', bukan 'Voy comer'. 'Vamos a…' juga bisa berarti 'Ayo…': ¡Vamos a bailar!"]}]},{"id":"A2","name":["Elementary","Dasar"],"goal":["Talk about the past, routines and plans; deal with everyday situations.","Membicarakan masa lalu, rutinitas dan rencana; mengatasi situasi sehari-hari."],"topics":[{"id":"a2-reflexive","title":["Reflexive verbs (levantarse)","Kata kerja refleksif (levantarse)"],"what":["Reflexive verbs have a pronoun that refers back to the subject: me levanto (I get up, lit. 'I raise myself'). Many daily-routine verbs are reflexive. The pronoun goes before a conjugated verb or is attached to an infinitive or gerund.","Kata kerja refleksif punya kata ganti yang merujuk kembali ke subjek: me levanto (saya bangun, harfiah 'saya mengangkat diri'). Banyak kata kerja rutinitas harian bersifat refleksif. Kata gantinya diletakkan sebelum kata kerja terkonjugasi atau disambung ke infinitif atau gerundio."],"pattern":[{"head":[["Person","Persona"],["Pronoun","Kata ganti"],"levantarse","acostarse (o → ue)"],"rows":[["yo","{me}","{me} levanto","{me} acuesto"],["tú","{te}","{te} levantas","{te} acuestas"],["él / ella / usted","{se}","{se} levanta","{se} acuesta"],["nosotros","{nos}","{nos} levantamos","{nos} acostamos"],["vosotros","{os}","{os} levantáis","{os} acostáis"],["ellos / ustedes","{se}","{se} levantan","{se} acuestan"]],"note":["Others: ducharse, lavarse, vestirse (e → i), despertarse (e → ie), llamarse, quedarse, sentarse. With a body part use the article, not a possessive: me lavo las manos.","Lainnya: ducharse, lavarse, vestirse (e → i), despertarse (e → ie), llamarse, quedarse, sentarse. Dengan bagian tubuh pakai artikel, bukan kata kepemilikan: me lavo las manos."]},{"title":["Where the pronoun goes","Letak kata ganti"],"head":[["Verb form","Bentuk kata kerja"],["Example","Contoh"]],"rows":[[["conjugated verb","kata kerja terkonjugasi"],"{Me} ducho por la mañana."],[["infinitive","infinitif"],"Voy a duchar{me}. = {Me} voy a duchar."],[["gerund","gerundio"],"Estoy duchándo{me}. = {Me} estoy duchando."]]}],"examples":[["Me levanto a las siete.",["I get up at seven.","Saya bangun pukul tujuh."]],["Los niños se acuestan temprano.",["The children go to bed early.","Anak-anak tidur lebih awal."]],["¿Cómo te llamas?",["What's your name?","Siapa namamu?"]]],"tip":["Some verbs change meaning when reflexive: ir (go) / irse (leave), dormir (sleep) / dormirse (fall asleep), llamar (call) / llamarse (be called).","Beberapa kata kerja berubah arti saat refleksif: ir (pergi) / irse (pergi meninggalkan), dormir (tidur) / dormirse (tertidur), llamar (memanggil) / llamarse (bernama)."]},{"id":"a2-preterite-regular","title":["Preterite: regular verbs","Preterit: kata kerja beraturan"],"what":["The preterite (pretérito indefinido) tells completed actions at a finished time in the past: ayer, el lunes, en 2020, hace dos años. -er and -ir verbs share one set of endings. Note the written accents on yo and él forms.","Preterit (pretérito indefinido) menceritakan tindakan yang selesai pada waktu lampau yang sudah berakhir: ayer, el lunes, en 2020, hace dos años. Kata kerja -er dan -ir memakai akhiran yang sama. Perhatikan tanda aksen pada bentuk yo dan él."],"pattern":[{"head":[["Person","Persona"],"hablar","comer","vivir"],"rows":[["yo","habl{é}","com{í}","viv{í}"],["tú","habl{aste}","com{iste}","viv{iste}"],["él / ella / usted","habl{ó}","com{ió}","viv{ió}"],["nosotros","habl{amos}","com{imos}","viv{imos}"],["vosotros","habl{asteis}","com{isteis}","viv{isteis}"],["ellos / ustedes","habl{aron}","com{ieron}","viv{ieron}"]],"note":["Spelling changes in the yo form keep the sound: buscar → bus{qué}, llegar → lle{gué}, empezar → empe{cé}. Between vowels i becomes y: leer → le{yó}, le{yeron}.","Perubahan ejaan pada bentuk yo menjaga bunyinya: buscar → bus{qué}, llegar → lle{gué}, empezar → empe{cé}. Di antara vokal, i menjadi y: leer → le{yó}, le{yeron}."]}],"examples":[["Ayer trabajé diez horas.",["Yesterday I worked ten hours.","Kemarin saya bekerja sepuluh jam."]],["¿Viste el partido?",["Did you see the match?","Kamu menonton pertandingannya?"]],["Vivieron en Chile dos años.",["They lived in Chile for two years.","Mereka tinggal di Chili selama dua tahun."]]],"tip":["For -ar verbs, nosotros is the same in the present and the preterite (hablamos); the time word tells you which one is meant: hoy hablamos / ayer hablamos.","Untuk kata kerja -ar, bentuk nosotros sama di kala kini dan preterit (hablamos); kata keterangan waktu menunjukkan mana yang dimaksud: hoy hablamos / ayer hablamos."]},{"id":"a2-preterite-irregular","title":["Preterite: irregular verbs","Preterit: kata kerja tidak beraturan"],"what":["Many frequent verbs have an irregular stem in the preterite and share special endings without accents (-e, -iste, -o, -imos, -isteis, -ieron). Ser and ir have the same preterite: fui, fuiste, fue… — the context shows which verb it is.","Banyak kata kerja umum punya akar tidak beraturan pada preterit dan memakai akhiran khusus tanpa aksen (-e, -iste, -o, -imos, -isteis, -ieron). Ser dan ir punya preterit yang sama: fui, fuiste, fue… — konteks menunjukkan kata kerja mana yang dimaksud."],"pattern":[{"title":["Irregular stems","Akar tidak beraturan"],"head":[["Infinitive","Infinitif"],["Stem","Akar"],"yo","él / ella","ellos"],"rows":[["tener","{tuv}-","tuve","tuvo","tuvieron"],["estar","{estuv}-","estuve","estuvo","estuvieron"],["poder","{pud}-","pude","pudo","pudieron"],["poner","{pus}-","puse","puso","pusieron"],["saber","{sup}-","supe","supo","supieron"],["hacer","{hic}- / {hiz}-","hice","hizo","hicieron"],["querer","{quis}-","quise","quiso","quisieron"],["venir","{vin}-","vine","vino","vinieron"],["decir","{dij}-","dije","dijo","dij{eron}"],["traer","{traj}-","traje","trajo","traj{eron}"]],"note":["Stems ending in j drop the i in the ellos form: dijeron, trajeron, condujeron.","Akar yang berakhiran j kehilangan i pada bentuk ellos: dijeron, trajeron, condujeron."]},{"title":["ser / ir, dar, and -ir stem changers","ser / ir, dar, dan -ir dengan perubahan akar"],"head":[["Person","Persona"],"ser / ir","dar","pedir (e → i)","dormir (o → u)"],"rows":[["yo","{fui}","{di}","pedí","dormí"],["tú","{fuiste}","{diste}","pediste","dormiste"],["él / ella / usted","{fue}","{dio}","p{i}dió","d{u}rmió"],["nosotros","{fuimos}","{dimos}","pedimos","dormimos"],["vosotros","{fuisteis}","{disteis}","pedisteis","dormisteis"],["ellos / ustedes","{fueron}","{dieron}","p{i}dieron","d{u}rmieron"]]}],"examples":[["El sábado fuimos a la playa.",["On Saturday we went to the beach.","Hari Sabtu kami pergi ke pantai."]],["No pude dormir anoche.",["I couldn't sleep last night.","Saya tidak bisa tidur tadi malam."]],["¿Qué hiciste el fin de semana?",["What did you do at the weekend?","Apa yang kamu lakukan akhir pekan lalu?"]]],"tip":["Irregular preterites have no written accent: hice, hizo, tuve, tuvo, fui, fue. Compare the regular habló, comió.","Preterit tidak beraturan tidak memakai tanda aksen: hice, hizo, tuve, tuvo, fui, fue. Bandingkan dengan yang beraturan habló, comió."]},{"id":"a2-imperfect","title":["Imperfect: past habits and descriptions","Imperfek: kebiasaan dan deskripsi masa lalu"],"what":["The imperfect (pretérito imperfecto) describes how things were and what used to happen: background, habits, age, time, ongoing situations. It is very regular: only ser, ir and ver are irregular.","Imperfek (pretérito imperfecto) menggambarkan keadaan masa lalu dan hal yang biasa terjadi: latar, kebiasaan, umur, waktu, situasi yang sedang berlangsung. Bentuknya sangat beraturan: hanya ser, ir dan ver yang tidak beraturan."],"pattern":[{"head":[["Person","Persona"],"hablar","comer / vivir","ser","ir","ver"],"rows":[["yo","habl{aba}","com{ía}","{era}","{iba}","{veía}"],["tú","habl{abas}","com{ías}","{eras}","{ibas}","{veías}"],["él / ella / usted","habl{aba}","com{ía}","{era}","{iba}","{veía}"],["nosotros","habl{ábamos}","com{íamos}","{éramos}","{íbamos}","{veíamos}"],["vosotros","habl{abais}","com{íais}","{erais}","{ibais}","{veíais}"],["ellos / ustedes","habl{aban}","com{ían}","{eran}","{iban}","{veían}"]],"note":["Typical words: antes, de pequeño, cuando era niño, siempre, todos los días, normalmente, a menudo. hay → había (there was / were).","Kata khas: antes, de pequeño, cuando era niño, siempre, todos los días, normalmente, a menudo. hay → había (dulu ada)."]}],"examples":[["De niño vivía en el campo.",["As a child I lived in the countryside.","Waktu kecil saya tinggal di desa."]],["Todos los veranos íbamos a la playa.",["Every summer we used to go to the beach.","Setiap musim panas kami biasa pergi ke pantai."]],["Eran las diez y hacía frío.",["It was ten o'clock and it was cold.","Saat itu pukul sepuluh dan udaranya dingin."]]],"tip":["Yo and él forms are identical (yo hablaba, él hablaba), so add the subject when it isn't clear from context.","Bentuk yo dan él sama (yo hablaba, él hablaba), jadi tambahkan subjek bila konteksnya kurang jelas."]},{"id":"a2-pret-imp","title":["Preterite or imperfect?","Preterit atau imperfek?"],"what":["In a story, the preterite moves the action forward (what happened next), and the imperfect paints the background (what was going on, what things were like). An action in progress (imperfect) is often interrupted by a new event (preterite).","Dalam cerita, preterit memajukan alur (apa yang terjadi berikutnya), sedangkan imperfek melukiskan latarnya (apa yang sedang terjadi, bagaimana keadaannya). Tindakan yang sedang berlangsung (imperfek) sering disela oleh peristiwa baru (preterit)."],"pattern":[{"head":[["Preterite","Preterit"],["Imperfect","Imperfek"]],"rows":[[["completed event: Ayer {comí} paella.","peristiwa selesai: Ayer {comí} paella."],["habit: Siempre {comía} paella.","kebiasaan: Siempre {comía} paella."]],[["sequence of events: {Llegué}, {cené} y {salí}.","urutan peristiwa: {Llegué}, {cené} y {salí}."],["background: {Hacía} sol y {había} mucha gente.","latar: {Hacía} sol y {había} mucha gente."]],[["new event interrupting: …cuando {sonó} el teléfono.","peristiwa baru yang menyela: …cuando {sonó} el teléfono."],["action in progress: {Dormía}…","tindakan berlangsung: {Dormía}…"]],[["fixed duration: {Viví} allí tres años.","durasi tertentu: {Viví} allí tres años."],["description, age, time: {Tenía} ocho años. {Eran} las dos.","deskripsi, umur, jam: {Tenía} ocho años. {Eran} las dos."]]]}],"examples":[["Leía un libro cuando llegó Carlos.",["I was reading a book when Carlos arrived.","Saya sedang membaca buku ketika Carlos datang."]],["Cuando era pequeña, tenía un perro.",["When I was little, I had a dog.","Waktu saya kecil, saya punya anjing."]],["Ayer fui al médico porque me dolía la cabeza.",["Yesterday I went to the doctor because I had a headache.","Kemarin saya ke dokter karena kepala saya sakit."]]],"tip":["Ask: 'Could I film it as one event with a start and end?' → preterite. 'Is it the scenery or the situation?' → imperfect.","Tanyakan: 'Bisakah saya merekamnya sebagai satu peristiwa dengan awal dan akhir?' → preterit. 'Apakah itu latar atau situasinya?' → imperfek."]},{"id":"a2-perfect","title":["Present perfect (he hablado)","Present perfect (he hablado)"],"what":["Haber in the present + past participle. In Spain it is used for past actions in a time period that is still open (hoy, esta semana, este año) and for experiences (alguna vez, nunca, ya, todavía no). Much of Latin America prefers the preterite for these.","Haber dalam kala kini + partisip lampau. Di Spanyol bentuk ini dipakai untuk tindakan lampau dalam periode yang belum berakhir (hoy, esta semana, este año) dan untuk pengalaman (alguna vez, nunca, ya, todavía no). Sebagian besar Amerika Latin lebih memilih preterit untuk hal ini."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"haber",["participle","partisip"]],"rows":[["yo","{he}","habl{ado}"],["tú","{has}","com{ido}"],["él / ella / usted","{ha}","viv{ido}"],["nosotros","{hemos}","trabaj{ado}"],["vosotros","{habéis}","sal{ido}"],["ellos / ustedes","{han}","le{ído}"]]},{"title":["Irregular participles","Partisip tidak beraturan"],"head":[["Infinitive","Infinitif"],["Participle","Partisip"],["Infinitive","Infinitif"],["Participle","Partisip"]],"rows":[["hacer","{hecho}","ver","{visto}"],["decir","{dicho}","escribir","{escrito}"],["poner","{puesto}","abrir","{abierto}"],["volver","{vuelto}","romper","{roto}"],["morir","{muerto}","descubrir","{descubierto}"]]}],"examples":[["Hoy he trabajado mucho.",["I've worked a lot today.","Hari ini saya sudah bekerja banyak."]],["¿Has estado alguna vez en México?",["Have you ever been to Mexico?","Pernahkah kamu ke Meksiko?"]],["Todavía no hemos comido.",["We haven't eaten yet.","Kami belum makan."]]],"tip":["Never split haber and the participle and never change the participle: 'Lo he visto', 'Ella ha salido' — not 'ha salida', not 'he lo visto'.","Jangan memisahkan haber dan partisipnya dan jangan mengubah partisipnya: 'Lo he visto', 'Ella ha salido' — bukan 'ha salida', bukan 'he lo visto'."]},{"id":"a2-continuous","title":["Estar + gerund (actions in progress)","Estar + gerundio (tindakan yang sedang berlangsung)"],"what":["Estar + gerund describes what is happening right now or around now. The gerund ends in -ando (-ar verbs) or -iendo (-er/-ir verbs). Use it less than English '-ing': never for the future and rarely with ser, ir or venir.","Estar + gerundio menggambarkan apa yang sedang terjadi sekarang atau belakangan ini. Gerundio berakhiran -ando (kata kerja -ar) atau -iendo (kata kerja -er/-ir). Pemakaiannya lebih jarang daripada '-ing' bahasa Inggris: tidak pernah untuk masa depan dan jarang dengan ser, ir atau venir."],"pattern":[{"head":[["Infinitive","Infinitif"],["Gerund","Gerundio"],["Example","Contoh"]],"rows":[["hablar","habl{ando}","Estoy {hablando} por teléfono."],["comer","com{iendo}","Estamos {comiendo}."],["escribir","escrib{iendo}","Está {escribiendo} un correo."],["leer / oír / ir","le{yendo} / o{yendo} / {yendo}","Estoy {leyendo}."],["dormir / decir / pedir","d{u}rmiendo / d{i}ciendo / p{i}diendo","El bebé está {durmiendo}."]],"note":["Past: estaba + gerund — Estaba cocinando cuando llamaste.","Lampau: estaba + gerundio — Estaba cocinando cuando llamaste."]}],"examples":[["¿Qué estás haciendo?",["What are you doing?","Kamu sedang apa?"]],["Está lloviendo.",["It's raining.","Sedang hujan."]],["Estaba durmiendo cuando sonó el teléfono.",["I was sleeping when the phone rang.","Saya sedang tidur ketika telepon berbunyi."]]],"tip":["For plans use the present or ir a: 'Mañana salgo / voy a salir', never 'Mañana estoy saliendo'.","Untuk rencana pakai kala kini atau ir a: 'Mañana salgo / voy a salir', jangan 'Mañana estoy saliendo'."]},{"id":"a2-direct-objects","title":["Direct object pronouns (lo, la, los, las)","Kata ganti objek langsung (lo, la, los, las)"],"what":["Direct object pronouns replace the thing or person that receives the action. In the third person they agree in gender and number with the noun they replace. They go before a conjugated verb, or attach to an infinitive, gerund or affirmative command.","Kata ganti objek langsung menggantikan benda atau orang yang dikenai tindakan. Untuk persona ketiga, bentuknya menyesuaikan gender dan jumlah kata benda yang digantikan. Diletakkan sebelum kata kerja terkonjugasi, atau disambung ke infinitif, gerundio atau perintah positif."],"pattern":[{"head":[["Person","Persona"],["Pronoun","Kata ganti"],["Example","Contoh"]],"rows":[[["me","saya"],"{me}","¿{Me} ves?"],[["you (tú)","kamu"],"{te}","{Te} quiero."],[["him / it (m.) / you (Ud., m.)","dia / itu (m.) / Anda (m.)"],"{lo}","El libro: {lo} tengo."],[["her / it (f.) / you (Ud., f.)","dia / itu (f.) / Anda (f.)"],"{la}","La carta: {la} escribo."],[["us","kami"],"{nos}","{Nos} llaman."],[["you all (vosotros)","kalian"],"{os}","{Os} invito."],[["them / you all (m.)","mereka / kalian (m.)"],"{los}","Los zapatos: {los} compro."],[["them / you all (f.)","mereka / kalian (f.)"],"{las}","Las llaves: no {las} encuentro."]],"note":["Position: Lo quiero comprar = Quiero comprarlo. Lo estoy leyendo = Estoy leyéndolo. Command: ¡Cómpralo!","Posisi: Lo quiero comprar = Quiero comprarlo. Lo estoy leyendo = Estoy leyéndolo. Perintah: ¡Cómpralo!"]}],"examples":[["¿Tienes el pasaporte? — Sí, lo tengo.",["Do you have the passport? — Yes, I have it.","Kamu bawa paspor? — Ya, saya bawa."]],["Las flores, las compré ayer.",["The flowers, I bought them yesterday.","Bunga-bunga itu saya beli kemarin."]],["Voy a llamarte mañana.",["I'm going to call you tomorrow.","Saya akan meneleponmu besok."]]],"tip":["Choose lo or la by the noun's gender, not the meaning: la película → la vi; el coche → lo vendí.","Pilih lo atau la menurut gender kata bendanya, bukan artinya: la película → la vi; el coche → lo vendí."]},{"id":"a2-indirect-objects","title":["Indirect object pronouns (le, les)","Kata ganti objek tak langsung (le, les)"],"what":["Indirect object pronouns say to whom or for whom something is done: give, send, say, write, buy for. Spanish usually keeps the pronoun even when the person is named: Le doy el libro a Carlos.","Kata ganti objek tak langsung menyatakan kepada atau untuk siapa sesuatu dilakukan: memberi, mengirim, mengatakan, menulis, membelikan. Bahasa Spanyol biasanya tetap memakai kata ganti meskipun orangnya disebut: Le doy el libro a Carlos."],"pattern":[{"head":[["Person","Persona"],["Pronoun","Kata ganti"],["Example","Contoh"]],"rows":[[["to me","kepada saya"],"{me}","{Me} dio un regalo."],[["to you (tú)","kepadamu"],"{te}","¿{Te} escribo mañana?"],[["to him / her / you (Ud.)","kepadanya / kepada Anda"],"{le}","{Le} digo la verdad."],[["to us","kepada kami"],"{nos}","{Nos} explicó el problema."],[["to you all (vosotros)","kepada kalian"],"{os}","{Os} mando una foto."],[["to them / you all (Uds.)","kepada mereka / kalian"],"{les}","{Les} compré un regalo a mis padres."]],"note":["le and les do not change for gender. Only the 3rd person differs from the direct pronouns (lo/la vs le).","le dan les tidak berubah menurut gender. Hanya persona ketiga yang berbeda dari kata ganti langsung (lo/la vs le)."]}],"examples":[["¿Me pasas la sal?",["Can you pass me the salt?","Bisa tolong ambilkan garam?"]],["Le escribí a Lucía.",["I wrote to Lucía.","Saya menulis surat kepada Lucía."]],["Les voy a enseñar la ciudad.",["I'm going to show them the city.","Saya akan menunjukkan kota ini kepada mereka."]]],"tip":["Same position rules as direct pronouns: before a conjugated verb, or attached to an infinitive, gerund or affirmative command: Dime la verdad.","Aturan letaknya sama dengan kata ganti langsung: sebelum kata kerja terkonjugasi, atau disambung ke infinitif, gerundio atau perintah positif: Dime la verdad."]},{"id":"a2-comparison","title":["Comparatives & superlatives","Perbandingan & superlatif"],"what":["Compare with más/menos … que and tan … como (for adjectives/adverbs) or tanto/a/os/as … como (for nouns). The superlative is el/la/los/las + más + adjective (+ de). A few adjectives have irregular forms.","Bandingkan dengan más/menos … que dan tan … como (untuk kata sifat/keterangan) atau tanto/a/os/as … como (untuk kata benda). Superlatif = el/la/los/las + más + kata sifat (+ de). Beberapa kata sifat punya bentuk tidak beraturan."],"pattern":[{"title":["Patterns","Pola"],"head":[["Meaning","Arti"],["Pattern","Pola"],["Example","Contoh"]],"rows":[[["more … than","lebih … daripada"],"{más} + adj + {que}","Madrid es {más} grande {que} Sevilla."],[["less … than","kurang … daripada"],"{menos} + adj + {que}","Es {menos} caro {que} el otro."],[["as … as","se… / sama … dengan"],"{tan} + adj + {como}","Es {tan} alto {como} su padre."],[["as much / many … as","sebanyak … seperti"],"{tanto/a/os/as} + noun + {como}","Tengo {tantos} libros {como} tú."],[["the most … (in)","paling … (di)"],"el/la + {más} + adj + {de}","Es la ciudad {más} bonita {del} país."],[["very, extremely","sangat"],"adj + {-ísimo}","Es carísimo. Está buenísima."]]},{"title":["Irregular","Tidak beraturan"],"head":[["Adjective","Kata sifat"],["Comparative","Komparatif"]],"rows":[["bueno / bien","{mejor}"],["malo / mal","{peor}"],[["grande (age)","grande (umur)"],"{mayor}"],[["pequeño (age)","pequeño (umur)"],"{menor}"]]}],"examples":[["Mi hermano es mayor que yo.",["My brother is older than me.","Kakak laki-laki saya lebih tua dari saya."]],["Este es el mejor restaurante de la ciudad.",["This is the best restaurant in the city.","Ini restoran terbaik di kota ini."]],["No hace tanto frío como ayer.",["It's not as cold as yesterday.","Tidak sedingin kemarin."]]],"tip":["Never 'más bueno' or 'más mejor' for 'better': use mejor. With numbers 'more than' is más de: más de cien personas.","Jangan 'más bueno' atau 'más mejor' untuk 'lebih baik': pakai mejor. Dengan angka, 'lebih dari' adalah más de: más de cien personas."]},{"id":"a2-future","title":["Simple future (hablaré)","Kala depan sederhana (hablaré)"],"what":["The simple future adds the same endings to the whole infinitive for all verbs. It is used for predictions, promises and more formal statements about the future; in conversation ir a is more common. Twelve common verbs have a shortened stem.","Kala depan sederhana menambahkan akhiran yang sama ke seluruh infinitif untuk semua kata kerja. Dipakai untuk prediksi, janji dan pernyataan yang lebih resmi tentang masa depan; dalam percakapan ir a lebih umum. Dua belas kata kerja umum punya akar yang dipendekkan."],"pattern":[{"title":["Endings","Akhiran"],"head":[["Person","Persona"],["Ending","Akhiran"],["Example","Contoh"]],"rows":[["yo","{-é}","hablar{é}"],["tú","{-ás}","comer{ás}"],["él / ella / usted","{-á}","vivir{á}"],["nosotros","{-emos}","hablar{emos}"],["vosotros","{-éis}","comer{éis}"],["ellos / ustedes","{-án}","vivir{án}"]]},{"title":["Irregular stems","Akar tidak beraturan"],"head":[["Infinitive","Infinitif"],["Stem","Akar"],["Infinitive","Infinitif"],["Stem","Akar"]],"rows":[["tener","{tendr}-","hacer","{har}-"],["poner","{pondr}-","decir","{dir}-"],["salir","{saldr}-","poder","{podr}-"],["venir","{vendr}-","saber","{sabr}-"],["haber (habrá)","{habr}-","querer","{querr}-"]]}],"examples":[["Mañana lloverá en el norte.",["Tomorrow it will rain in the north.","Besok akan turun hujan di utara."]],["Te llamaré esta noche.",["I'll call you tonight.","Saya akan meneleponmu malam ini."]],["¿Vendrás a la fiesta?",["Will you come to the party?","Kamu akan datang ke pesta?"]]],"tip":["The future also expresses a guess about the present: ¿Dónde está Carlos? — Estará en casa (He's probably at home).","Kala depan juga menyatakan dugaan tentang saat ini: ¿Dónde está Carlos? — Estará en casa (Mungkin dia di rumah)."]},{"id":"a2-imperative","title":["Imperative: tú and vosotros (affirmative)","Imperatif: tú dan vosotros (positif)"],"what":["The affirmative tú command is the same as the él form of the present (habla, come). Eight common verbs are irregular. The vosotros command replaces -r of the infinitive with -d. Pronouns are attached to the end.","Perintah positif untuk tú sama dengan bentuk él kala kini (habla, come). Delapan kata kerja umum tidak beraturan. Perintah vosotros mengganti -r infinitif dengan -d. Kata ganti disambung di akhir."],"pattern":[{"title":["Regular","Beraturan"],"head":[["Infinitive","Infinitif"],"tú","vosotros"],"rows":[["hablar","habl{a}","habla{d}"],["comer","com{e}","come{d}"],["escribir","escrib{e}","escribi{d}"],["cerrar (e → ie)","c{ie}rra","cerra{d}"]]},{"title":["Irregular tú commands","Perintah tú tidak beraturan"],"head":[["Infinitive","Infinitif"],"tú",["Infinitive","Infinitif"],"tú"],"rows":[["decir","{di}","ir","{ve}"],["hacer","{haz}","poner","{pon}"],["salir","{sal}","ser","{sé}"],["tener","{ten}","venir","{ven}"]],"note":["With pronouns: siéntate, dímelo, hazlo. Reflexive vosotros drops the -d: sentaos, levantaos.","Dengan kata ganti: siéntate, dímelo, hazlo. Vosotros refleksif kehilangan -d: sentaos, levantaos."]}],"examples":[["Ven aquí, por favor.",["Come here, please.","Kemari, tolong."]],["Abre la ventana.",["Open the window.","Buka jendelanya."]],["Dime la verdad.",["Tell me the truth.","Katakan yang sebenarnya kepada saya."]]],"tip":["When you add pronouns, add an accent to keep the stress: compra → cómpralo, di + me + lo → dímelo.","Saat menambahkan kata ganti, tambahkan aksen agar tekanannya tetap: compra → cómpralo, di + me + lo → dímelo."]},{"id":"a2-indefinites","title":["Indefinites & double negation","Kata tak tentu & negasi ganda"],"what":["Pairs like algo/nada, alguien/nadie, siempre/nunca, también/tampoco. Spanish uses double negation: when a negative word comes after the verb, no must come before it. If the negative word comes first, no is dropped.","Pasangan seperti algo/nada, alguien/nadie, siempre/nunca, también/tampoco. Bahasa Spanyol memakai negasi ganda: jika kata negatif muncul setelah kata kerja, no harus diletakkan sebelumnya. Jika kata negatif di depan, no dihilangkan."],"pattern":[{"head":[["Positive","Positif"],["Negative","Negatif"],["Example","Contoh"]],"rows":[[["algo (something)","algo (sesuatu)"],["nada (nothing)","nada (tidak ada apa-apa)"],"{No} quiero {nada}."],[["alguien (someone)","alguien (seseorang)"],["nadie (no one)","nadie (tidak seorang pun)"],"{No} hay {nadie}. = {Nadie} está."],[["alguno/a (some, any)","alguno/a (beberapa, suatu)"],["ninguno/a (none, no)","ninguno/a (tidak satu pun)"],"{No} tengo {ningún} problema."],[["siempre (always)","siempre (selalu)"],["nunca (never)","nunca (tidak pernah)"],"{No} voy {nunca}. = {Nunca} voy."],[["también (also)","también (juga)"],["tampoco (neither)","tampoco (juga tidak)"],"Yo {tampoco}."]],"note":["alguno and ninguno lose -o before a masculine singular noun: algún día, ningún problema. ninguno is almost always singular.","alguno dan ninguno kehilangan -o sebelum kata benda maskulin tunggal: algún día, ningún problema. ninguno hampir selalu tunggal."]}],"examples":[["¿Quieres algo? — No, no quiero nada.",["Do you want anything? — No, I don't want anything.","Kamu mau sesuatu? — Tidak, saya tidak mau apa-apa."]],["Nunca bebo café.",["I never drink coffee.","Saya tidak pernah minum kopi."]],["¿Hay algún problema?",["Is there a problem?","Apakah ada masalah?"]]],"tip":["Double negation is correct, not a mistake: 'No veo a nadie' = I don't see anyone.","Negasi ganda itu benar, bukan kesalahan: 'No veo a nadie' = Saya tidak melihat siapa pun."]},{"id":"a2-por-para","title":["Por and para: the basics","Por dan para: dasar"],"what":["Both often translate as 'for', but para looks forward to a goal or destination (purpose, recipient, deadline, direction), while por looks at the cause or the way (reason, exchange, through, by means of, duration, approximate place).","Keduanya sering diterjemahkan 'untuk', tetapi para melihat ke depan ke tujuan (maksud, penerima, tenggat, arah), sedangkan por melihat ke sebab atau caranya (alasan, pertukaran, melalui, dengan sarana, durasi, tempat perkiraan)."],"pattern":[{"head":[["para","para"],["por","por"]],"rows":[[["purpose: Estudio {para} aprender.","tujuan: Estudio {para} aprender."],["cause: Lo hago {por} ti.","sebab: Lo hago {por} ti."]],[["recipient: Es {para} ti.","penerima: Es {para} ti."],["exchange, price: Lo compré {por} diez euros.","pertukaran, harga: Lo compré {por} diez euros."]],[["destination: Salgo {para} Madrid.","tujuan tempat: Salgo {para} Madrid."],["through, around: Paseo {por} el parque.","melalui, sekitar: Paseo {por} el parque."]],[["deadline: {Para} el lunes.","tenggat: {Para} el lunes."],["means: {por} teléfono, {por} correo","sarana: {por} teléfono, {por} correo"]],[["opinion: {Para} mí, es fácil.","pendapat: {Para} mí, es fácil."],["part of day: {por} la mañana","bagian hari: {por} la mañana"]]]}],"examples":[["Gracias por todo.",["Thanks for everything.","Terima kasih atas segalanya."]],["Este regalo es para tu madre.",["This present is for your mother.","Hadiah ini untuk ibumu."]],["Te llamo por la tarde.",["I'll call you in the afternoon.","Saya telepon kamu sore nanti."]]],"tip":["Fixed phrases with por: gracias por, por favor, por eso, por ejemplo, por fin, por supuesto. Para + infinitive = in order to.","Ungkapan tetap dengan por: gracias por, por favor, por eso, por ejemplo, por fin, por supuesto. Para + infinitif = supaya / untuk."]},{"id":"a2-muy-mucho","title":["Muy or mucho?","Muy atau mucho?"],"what":["Muy (very) goes before adjectives and adverbs and never changes. Mucho (a lot, much, many) goes with nouns, where it agrees (mucha agua, muchos libros), and after verbs, where it does not change (trabajo mucho).","Muy (sangat) diletakkan sebelum kata sifat dan kata keterangan dan tidak pernah berubah. Mucho (banyak) dipakai dengan kata benda dan menyesuaikannya (mucha agua, muchos libros), serta setelah kata kerja tanpa berubah (trabajo mucho)."],"pattern":[{"head":[["Word","Kata"],["Goes with","Dipakai dengan"],["Example","Contoh"]],"rows":[["{muy}",["adjective / adverb","kata sifat / keterangan"],"{muy} bonito, {muy} bien, {muy} tarde"],["{mucho / mucha}",["singular noun","kata benda tunggal"],"{mucho} tiempo, {mucha} gente"],["{muchos / muchas}",["plural noun","kata benda jamak"],"{muchos} amigos, {muchas} veces"],["{mucho}",["after a verb","setelah kata kerja"],"Te quiero {mucho}. Llueve {mucho}."],["{mucho} + más / menos / mejor / peor",["comparatives","perbandingan"],"{mucho} mejor, {mucho} más caro"]]}],"examples":[["Estoy muy cansado.",["I'm very tired.","Saya sangat lelah."]],["Hay mucha gente aquí.",["There are a lot of people here.","Banyak orang di sini."]],["Me gusta mucho.",["I like it a lot.","Saya sangat menyukainya."]]],"tip":["Never 'muy mucho'. Alone as an answer use mucho: ¿Te gusta? — Sí, mucho. And with comparatives use mucho: mucho mejor, not 'muy mejor'.","Jangan pernah 'muy mucho'. Sebagai jawaban tunggal pakai mucho: ¿Te gusta? — Sí, mucho. Dengan perbandingan pakai mucho: mucho mejor, bukan 'muy mejor'."]},{"id":"a2-dates","title":["Dates, ordinals & weather","Tanggal, bilangan bertingkat & cuaca"],"what":["Dates use cardinal numbers with el and de: el 3 de mayo (only 'el primero' is sometimes ordinal). Days and months are written in lower case. Ordinals (primero, segundo…) agree like adjectives. Weather uses hacer, estar and hay.","Tanggal memakai angka biasa dengan el dan de: el 3 de mayo (hanya 'el primero' kadang bertingkat). Hari dan bulan ditulis dengan huruf kecil. Bilangan bertingkat (primero, segundo…) menyesuaikan seperti kata sifat. Cuaca memakai hacer, estar dan hay."],"pattern":[{"title":["Dates and ordinals","Tanggal dan bilangan bertingkat"],"head":[["Use","Pemakaian"],["Spanish","Spanyol"]],"rows":[[["date","tanggal"],"Hoy es {el} 12 {de} octubre {de} 2026."],[["on Monday / on Mondays","pada hari Senin / setiap Senin"],"{el} lunes / {los} lunes"],[["in May / in 2026","pada bulan Mei / pada tahun 2026"],"{en} mayo / {en} 2026"],[["1st–5th","ke-1–ke-5"],"primero, segundo, tercero, cuarto, quinto"],[["before masc. sg. noun","sebelum kata benda mask. tg."],"el {primer} piso, el {tercer} día"]]},{"title":["Weather","Cuaca"],"head":[["Verb","Kata kerja"],["Spanish","Spanyol"],["Meaning","Arti"]],"rows":[["hacer","{Hace} calor / frío / sol / viento.",["It's hot / cold / sunny / windy.","Panas / dingin / cerah / berangin."]],["hacer","{Hace} buen / mal tiempo.",["The weather is good / bad.","Cuacanya baik / buruk."]],["estar","{Está} nublado.",["It's cloudy.","Berawan."]],["verbs","{Llueve}. {Nieva}.",["It rains. It snows.","Hujan. Turun salju."]],["hay","{Hay} niebla / tormenta.",["It's foggy / stormy.","Berkabut / ada badai."]]]}],"examples":[["Mi cumpleaños es el 25 de julio.",["My birthday is on 25 July.","Ulang tahun saya tanggal 25 Juli."]],["Vivo en el tercer piso.",["I live on the third floor.","Saya tinggal di lantai tiga."]],["En invierno hace mucho frío.",["In winter it's very cold.","Di musim dingin udaranya sangat dingin."]]],"tip":["No preposition before days: 'Te veo el lunes' (on Monday), not 'en el lunes'. With weather nouns use mucho: hace mucho calor.","Tanpa kata depan sebelum nama hari: 'Te veo el lunes', bukan 'en el lunes'. Dengan kata benda cuaca pakai mucho: hace mucho calor."]}]},{"id":"B1","name":["Intermediate","Menengah"],"goal":["Express wishes, feelings, opinions and hypotheses; tell and report stories.","Menyatakan keinginan, perasaan, pendapat dan pengandaian; menceritakan dan melaporkan kisah."],"topics":[{"id":"b1-subj-forms","title":["Present subjunctive: forms","Subjuntif kini: bentuk"],"what":["The subjunctive is a verb mood used mainly in subordinate clauses after que. To form it, take the yo form of the present, drop -o and add the 'opposite' vowel endings: -ar verbs take -e, -er/-ir verbs take -a. So any yo irregularity carries over (tengo → tenga).","Subjuntif adalah modus kata kerja yang terutama dipakai dalam anak kalimat setelah que. Cara membentuknya: ambil bentuk yo kala kini, buang -o, lalu tambahkan akhiran dengan vokal 'kebalikan': kata kerja -ar memakai -e, kata kerja -er/-ir memakai -a. Jadi ketidakteraturan bentuk yo ikut terbawa (tengo → tenga)."],"pattern":[{"title":["Regular and yo-based","Beraturan dan berbasis yo"],"head":[["Person","Persona"],"hablar","comer","vivir","tener (tengo)"],"rows":[["yo","habl{e}","com{a}","viv{a}","teng{a}"],["tú","habl{es}","com{as}","viv{as}","teng{as}"],["él / ella / usted","habl{e}","com{a}","viv{a}","teng{a}"],["nosotros","habl{emos}","com{amos}","viv{amos}","teng{amos}"],["vosotros","habl{éis}","com{áis}","viv{áis}","teng{áis}"],["ellos / ustedes","habl{en}","com{an}","viv{an}","teng{an}"]],"note":["Stem changes follow the present (quiera, pueda), but -ir verbs also change in nosotros/vosotros: pidamos, durmamos, sintamos. Spelling: buscar → busque, llegar → llegue, empezar → empiece.","Perubahan akar mengikuti kala kini (quiera, pueda), tetapi kata kerja -ir juga berubah pada nosotros/vosotros: pidamos, durmamos, sintamos. Ejaan: buscar → busque, llegar → llegue, empezar → empiece."]},{"title":["Six irregular verbs","Enam kata kerja tidak beraturan"],"head":[["Infinitive","Infinitif"],"yo / él","nosotros","ellos"],"rows":[["ser","{sea}","{seamos}","{sean}"],["ir","{vaya}","{vayamos}","{vayan}"],["estar","{esté}","{estemos}","{estén}"],["haber","{haya}","{hayamos}","{hayan}"],["saber","{sepa}","{sepamos}","{sepan}"],["dar","{dé}","{demos}","{den}"]]}],"examples":[["Espero que tengas suerte.",["I hope you're lucky.","Semoga kamu beruntung."]],["Quiero que vengáis.",["I want you (all) to come.","Saya ingin kalian datang."]],["Es posible que llueva.",["It may rain.","Mungkin akan hujan."]]],"tip":["Think 'yo-form minus -o, then swap the vowel': hago → haga, conozco → conozca, digo → diga. The six verbs in the second table are the only real exceptions.","Ingat 'bentuk yo minus -o, lalu tukar vokalnya': hago → haga, conozco → conozca, digo → diga. Enam kata kerja di tabel kedua adalah satu-satunya pengecualian sejati."]},{"id":"b1-subj-wishes","title":["Subjunctive after wishes, requests and advice","Subjuntif setelah keinginan, permintaan dan saran"],"what":["When one person wants, asks, advises or allows another person to do something, the second verb goes into the subjunctive after que. If the subject is the same person, use the infinitive instead. Ojalá (que) also takes the subjunctive.","Jika seseorang ingin, meminta, menyarankan atau mengizinkan orang lain melakukan sesuatu, kata kerja kedua memakai subjuntif setelah que. Jika subjeknya sama, pakai infinitif. Ojalá (que) juga diikuti subjuntif."],"pattern":[{"head":[["Same subject → infinitive","Subjek sama → infinitif"],["Different subject → que + subjunctive","Subjek beda → que + subjuntif"]],"rows":[["Quiero {salir}.","Quiero que {salgas}."],["Prefiero {quedarme}.","Prefiero que te {quedes}."],["Necesito {descansar}.","Necesito que me {ayudes}."],["—","Te pido que {vengas}. Te recomiendo que {pruebes} la sopa."],["—","{Ojalá} (que) {haga} buen tiempo."]],"note":["Verbs of this type: querer, desear, preferir, esperar, necesitar, pedir, rogar, recomendar, aconsejar, sugerir, permitir, prohibir, dejar.","Kata kerja jenis ini: querer, desear, preferir, esperar, necesitar, pedir, rogar, recomendar, aconsejar, sugerir, permitir, prohibir, dejar."]}],"examples":[["Mis padres quieren que estudie medicina.",["My parents want me to study medicine.","Orang tua saya ingin saya kuliah kedokteran."]],["¡Ojalá ganemos!",["I hope we win!","Semoga kita menang!"]],["Te recomiendo que vayas al museo.",["I recommend you go to the museum.","Saya sarankan kamu pergi ke museum."]]],"tip":["Never 'Quiero que yo salga' or 'Quiero tú salir': same person → infinitive; another person → que + subjunctive.","Jangan 'Quiero que yo salga' atau 'Quiero tú salir': orang yang sama → infinitif; orang lain → que + subjuntif."]},{"id":"b1-subj-feelings","title":["Subjunctive after feelings, doubt and evaluation","Subjuntif setelah perasaan, keraguan dan penilaian"],"what":["The subjunctive follows expressions of emotion (me alegra que, siento que), doubt or denial (dudo que, no creo que) and evaluations (es importante que, es normal que). Statements of belief or fact (creo que, es verdad que, está claro que) take the indicative.","Subjuntif dipakai setelah ungkapan emosi (me alegra que, siento que), keraguan atau penyangkalan (dudo que, no creo que) dan penilaian (es importante que, es normal que). Pernyataan keyakinan atau fakta (creo que, es verdad que, está claro que) memakai indikatif."],"pattern":[{"head":[["Type","Jenis"],["+ subjunctive","+ subjuntif"],["+ indicative","+ indikatif"]],"rows":[[["opinion","pendapat"],"No creo que {sea} verdad.","Creo que {es} verdad."],[["certainty","kepastian"],"Dudo que {venga}.","Estoy seguro de que {viene}."],[["truth","kebenaran"],"No es verdad que {esté} enfermo.","Es verdad que {está} enfermo."],[["emotion","emosi"],"Me alegra que {estés} aquí. Siento que {llegues} tarde.","—"],[["evaluation","penilaian"],"Es importante que {duermas}. Es una pena que no {puedas} venir.","Es obvio que {puedes}."]]}],"examples":[["No creo que llegue a tiempo.",["I don't think he'll arrive on time.","Saya tidak yakin dia akan tiba tepat waktu."]],["Me molesta que hables tan alto.",["It bothers me that you talk so loudly.","Saya terganggu kamu bicara sekeras itu."]],["Es normal que estés nervioso.",["It's normal that you're nervous.","Wajar kalau kamu gugup."]]],"tip":["The switch happens with negation: creo que + indicative, but no creo que + subjunctive. Pienso que es caro / No pienso que sea caro.","Perubahannya terjadi karena negasi: creo que + indikatif, tetapi no creo que + subjuntif. Pienso que es caro / No pienso que sea caro."]},{"id":"b1-subj-time","title":["Subjunctive in time and purpose clauses","Subjuntif dalam anak kalimat waktu dan tujuan"],"what":["After cuando, hasta que, en cuanto, antes de que and tan pronto como, use the subjunctive if the action is still in the future; use the indicative for habits or past facts. Para que (so that) and antes de que always take the subjunctive.","Setelah cuando, hasta que, en cuanto, antes de que dan tan pronto como, pakai subjuntif jika tindakannya masih di masa depan; pakai indikatif untuk kebiasaan atau fakta lampau. Para que (supaya) dan antes de que selalu diikuti subjuntif."],"pattern":[{"head":[["Conjunction","Konjungsi"],["Future → subjunctive","Masa depan → subjuntif"],["Habit / past → indicative","Kebiasaan / lampau → indikatif"]],"rows":[["cuando","Cuando {llegues}, llámame.","Cuando {llego}, siempre llamo. Cuando {llegué}, llamé."],["hasta que","Espera hasta que {vuelva}.","Esperé hasta que {volvió}."],["en cuanto","En cuanto {sepa} algo, te aviso.","En cuanto {supe} algo, te avisé."],["para que","Te lo digo para que lo {sepas}.","—"],["antes de que","Vámonos antes de que {llueva}.","—"]],"note":["With the same subject use the infinitive: para + infinitive, antes de + infinitive: Estudio para aprobar.","Jika subjeknya sama pakai infinitif: para + infinitif, antes de + infinitif: Estudio para aprobar."]}],"examples":[["Cuando tenga tiempo, te escribiré.",["When I have time, I'll write to you.","Kalau ada waktu, saya akan menulis kepadamu."]],["Te doy mi número para que me llames.",["I'm giving you my number so that you call me.","Saya beri nomor saya supaya kamu menelepon saya."]],["Nos quedamos hasta que terminó la película.",["We stayed until the film ended.","Kami tinggal sampai filmnya selesai."]]],"tip":["Never use the future after cuando: 'Cuando llegues', not 'Cuando llegarás'. Question cuándo (with an accent) is different: ¿Cuándo llegarás?","Jangan memakai kala depan setelah cuando: 'Cuando llegues', bukan 'Cuando llegarás'. Kata tanya cuándo (beraksen) berbeda: ¿Cuándo llegarás?"]},{"id":"b1-conditional","title":["Conditional (hablaría)","Kondisional (hablaría)"],"what":["The conditional adds -ía endings to the whole infinitive, with the same irregular stems as the future (tendría, haría, podría). It expresses what would happen, polite requests, advice, and guesses about the past.","Kondisional menambahkan akhiran -ía ke seluruh infinitif, dengan akar tidak beraturan yang sama seperti kala depan (tendría, haría, podría). Bentuk ini menyatakan apa yang akan terjadi (seandainya), permintaan sopan, saran, dan dugaan tentang masa lalu."],"pattern":[{"title":["Forms","Bentuk"],"head":[["Person","Persona"],"hablar","tener","hacer"],"rows":[["yo","hablar{ía}","tendr{ía}","har{ía}"],["tú","hablar{ías}","tendr{ías}","har{ías}"],["él / ella / usted","hablar{ía}","tendr{ía}","har{ía}"],["nosotros","hablar{íamos}","tendr{íamos}","har{íamos}"],["vosotros","hablar{íais}","tendr{íais}","har{íais}"],["ellos / ustedes","hablar{ían}","tendr{ían}","har{ían}"]]},{"title":["Uses","Pemakaian"],"head":[["Use","Pemakaian"],["Example","Contoh"]],"rows":[[["polite request","permintaan sopan"],"¿{Podría} ayudarme? Me {gustaría} un café."],[["advice","saran"],"Yo que tú, {hablaría} con él. {Deberías} descansar."],[["hypothesis","pengandaian"],"Con más dinero, {viajaría} más."],[["guess about the past","dugaan tentang masa lalu"],"{Serían} las diez cuando llegó."]]}],"examples":[["Me gustaría vivir en el extranjero.",["I'd like to live abroad.","Saya ingin tinggal di luar negeri."]],["¿Podrías cerrar la puerta?",["Could you close the door?","Bisakah kamu menutup pintu?"]],["Deberías dormir más.",["You should sleep more.","Kamu sebaiknya tidur lebih banyak."]]],"tip":["The conditional endings are the imperfect -er/-ir endings (-ía), but added to the infinitive: comía (I used to eat) vs comería (I would eat).","Akhiran kondisional sama dengan akhiran imperfek -er/-ir (-ía), tetapi ditambahkan ke infinitif: comía (dulu saya makan) vs comería (saya akan makan)."]},{"id":"b1-si","title":["Si clauses: real and hypothetical","Kalimat si: nyata dan pengandaian"],"what":["For real, possible conditions use si + present, then present, future or imperative. For unlikely or imaginary conditions use si + imperfect subjunctive, then the conditional. The imperfect subjunctive is formed from the ellos preterite: hablaron → hablara, tuvieron → tuviera.","Untuk syarat nyata yang mungkin terjadi pakai si + kala kini, lalu kala kini, kala depan atau imperatif. Untuk syarat yang kecil kemungkinannya atau khayalan pakai si + subjuntif imperfek, lalu kondisional. Subjuntif imperfek dibentuk dari preterit ellos: hablaron → hablara, tuvieron → tuviera."],"pattern":[{"title":["Two types","Dua jenis"],"head":[["Type","Jenis"],["si clause","anak kalimat si"],["main clause","induk kalimat"],["Example","Contoh"]],"rows":[[["real","nyata"],["si + present","si + kala kini"],["present / future / command","kini / depan / perintah"],"Si {tienes} tiempo, {ven}. Si {llueve}, no {saldré}."],[["hypothetical","pengandaian"],["si + imperfect subjunctive","si + subjuntif imperfek"],["conditional","kondisional"],"Si {tuviera} dinero, {compraría} una casa."]]},{"title":["Imperfect subjunctive from the preterite","Subjuntif imperfek dari preterit"],"head":[["Infinitive","Infinitif"],["ellos preterite","preterit ellos"],"yo / él","nosotros"],"rows":[["hablar","habla{ron}","habla{ra}","hablá{ramos}"],["tener","tuvie{ron}","tuvie{ra}","tuvié{ramos}"],["ser / ir","fue{ron}","fue{ra}","fué{ramos}"],["poder","pudie{ron}","pudie{ra}","pudié{ramos}"],["estar","estuvie{ron}","estuvie{ra}","estuvié{ramos}"]],"note":["An alternative -se form exists (hablase, tuviese) with the same meaning.","Ada juga bentuk alternatif -se (hablase, tuviese) dengan arti yang sama."]}],"examples":[["Si estudias, aprobarás.",["If you study, you'll pass.","Kalau kamu belajar, kamu akan lulus."]],["Si fuera tú, no lo haría.",["If I were you, I wouldn't do it.","Kalau saya jadi kamu, saya tidak akan melakukannya."]],["Si pudiera, viajaría por todo el mundo.",["If I could, I'd travel all over the world.","Kalau bisa, saya akan berkeliling dunia."]]],"tip":["Never put the present subjunctive or the conditional after si: 'Si tengo', 'Si tuviera' — never 'si tenga' or 'si tendría'.","Jangan pernah memakai subjuntif kini atau kondisional setelah si: 'Si tengo', 'Si tuviera' — bukan 'si tenga' atau 'si tendría'."]},{"id":"b1-pluperfect","title":["Pluperfect (había hablado)","Pluperfek (había hablado)"],"what":["Haber in the imperfect + past participle tells an action that happened before another past action: 'had done'. It is common with ya (already), todavía no and nunca antes.","Haber dalam imperfek + partisip lampau menceritakan tindakan yang terjadi sebelum tindakan lampau lainnya: 'sudah (lebih dulu)'. Bentuk ini sering dipakai dengan ya (sudah), todavía no dan nunca antes."],"pattern":[{"head":[["Person","Persona"],"haber",["participle","partisip"]],"rows":[["yo","{había}","hablado"],["tú","{habías}","comido"],["él / ella / usted","{había}","salido"],["nosotros","{habíamos}","visto"],["vosotros","{habíais}","hecho"],["ellos / ustedes","{habían}","vuelto"]]},{"title":["Timeline","Garis waktu"],"head":[["First (earlier past)","Lebih dulu (lampau lebih awal)"],["Then (past)","Kemudian (lampau)"]],"rows":[["El tren ya {había salido}","cuando {llegué} a la estación."],["Nunca antes {había visto}","el mar hasta que {fui} a Cádiz."]]}],"examples":[["Cuando llegamos, la película ya había empezado.",["When we arrived, the film had already started.","Ketika kami tiba, filmnya sudah dimulai."]],["No había estado nunca en Asia.",["I had never been to Asia.","Saya belum pernah ke Asia sebelumnya."]],["Me dijo que había perdido las llaves.",["She told me she had lost her keys.","Dia bilang dia kehilangan kuncinya."]]],"tip":["Use it only when the order of events matters. For a simple sequence told in order, the preterite is enough: Llegué, cené y me acosté.","Pakai hanya jika urutan peristiwa penting. Untuk urutan biasa yang diceritakan berurutan, preterit sudah cukup: Llegué, cené y me acosté."]},{"id":"b1-relative","title":["Relative pronouns: que, quien, donde, lo que","Kata ganti relatif: que, quien, donde, lo que"],"what":["Que is the all-purpose relative for people and things. After a preposition, people take quien/quienes (or el que), things take el que/la que. Donde is for places. Lo que means 'what' or 'which' referring to a whole idea.","Que adalah kata ganti relatif serbaguna untuk orang dan benda. Setelah kata depan, orang memakai quien/quienes (atau el que), benda memakai el que/la que. Donde untuk tempat. Lo que berarti 'apa yang' atau 'hal yang' untuk seluruh gagasan."],"pattern":[{"head":[["Relative","Relatif"],["Use","Pemakaian"],["Example","Contoh"]],"rows":[["{que}",["people or things","orang atau benda"],"El chico {que} vive aquí. El libro {que} leí."],["prep. + {quien/quienes}",["people after a preposition","orang setelah kata depan"],"La amiga con {quien} viajé."],["prep. + {el que / la que / los que / las que}",["people or things after a preposition","orang atau benda setelah kata depan"],"La casa en {la que} vivo. El tema del {que} hablamos."],["{donde}",["place","tempat"],"El pueblo {donde} nací."],["{lo que}",["what / which (idea)","apa yang / hal yang (gagasan)"],"No entiendo {lo que} dices. Llegó tarde, {lo que} me molestó."]]}],"examples":[["La mujer que me ayudó era enfermera.",["The woman who helped me was a nurse.","Perempuan yang membantu saya adalah perawat."]],["Esta es la ciudad donde conocí a mi marido.",["This is the city where I met my husband.","Ini kota tempat saya bertemu suami saya."]],["Haz lo que quieras.",["Do what(ever) you want.","Lakukan apa yang kamu mau."]]],"tip":["The preposition always goes before the relative, never at the end: 'el chico con el que salgo' (the guy I go out with).","Kata depan selalu diletakkan sebelum kata relatif, tidak pernah di akhir: 'el chico con el que salgo' (laki-laki yang saya kencani)."]},{"id":"b1-double-pronouns","title":["Two object pronouns together (se lo)","Dua kata ganti objek bersamaan (se lo)"],"what":["When an indirect and a direct pronoun appear together, the indirect one comes first: me lo, te la, nos los. If both start with l- (le/les + lo/la/los/las), le/les becomes se: se lo, se la.","Jika kata ganti tak langsung dan langsung muncul bersama, yang tak langsung lebih dulu: me lo, te la, nos los. Jika keduanya diawali l- (le/les + lo/la/los/las), le/les menjadi se: se lo, se la."],"pattern":[{"head":[["Indirect + direct","Tak langsung + langsung"],["Example","Contoh"]],"rows":[["{me lo / me la}","¿El libro? {Me lo} dio Ana."],["{te los / te las}","Las fotos: {te las} mando mañana."],["{nos lo / os lo}","{Nos lo} explicó el profesor."],["le / les + lo → {se lo}","Le doy el libro → {Se lo} doy."],["le / les + la → {se la}","Les enseño la casa → {Se la} enseño."]],"note":["Attached to infinitives, gerunds and affirmative commands: Quiero dártelo. Estoy explicándoselo. ¡Dímelo! (accent to keep the stress).","Disambung ke infinitif, gerundio dan perintah positif: Quiero dártelo. Estoy explicándoselo. ¡Dímelo! (beraksen untuk menjaga tekanan)."]}],"examples":[["¿Me prestas el coche? — Sí, te lo presto.",["Will you lend me the car? — Yes, I'll lend it to you.","Boleh pinjam mobilmu? — Ya, saya pinjamkan."]],["¿Le diste la carta a Lucía? — Sí, se la di ayer.",["Did you give the letter to Lucía? — Yes, I gave it to her yesterday.","Kamu sudah memberikan surat itu kepada Lucía? — Ya, saya berikan kemarin."]],["Cuéntamelo todo.",["Tell me everything.","Ceritakan semuanya kepada saya."]]],"tip":["'Le lo' does not exist: always se lo. The se here is just le in disguise, not the reflexive se.","'Le lo' tidak ada: selalu se lo. Se di sini hanya le yang menyamar, bukan se refleksif."]},{"id":"b1-imperative-formal","title":["Imperative: usted and negative commands","Imperatif: usted dan perintah negatif"],"what":["Usted/ustedes commands and all negative commands use present subjunctive forms: hable usted, no hables. In negative commands the pronouns go before the verb; in affirmative commands they are attached.","Perintah untuk usted/ustedes dan semua perintah negatif memakai bentuk subjuntif kini: hable usted, no hables. Dalam perintah negatif kata ganti diletakkan sebelum kata kerja; dalam perintah positif disambung."],"pattern":[{"head":[["Verb","Kata kerja"],["tú +","tú +"],["tú −","tú −"],["usted + / −","usted + / −"],["vosotros −","vosotros −"]],"rows":[["hablar","habla","no {hables}","{hable} / no {hable}","no {habléis}"],["comer","come","no {comas}","{coma} / no {coma}","no {comáis}"],["hacer","haz","no {hagas}","{haga} / no {haga}","no {hagáis}"],["ir","ve","no {vayas}","{vaya} / no {vaya}","no {vayáis}"],["decírselo","díselo","no {se lo digas}","{dígaselo} / no {se lo diga}","no {se lo digáis}"]]}],"examples":[["Pase, por favor. Siéntese.",["Come in, please. Sit down. (usted)","Silakan masuk. Silakan duduk. (usted)"]],["No te preocupes.",["Don't worry.","Jangan khawatir."]],["No lo toques.",["Don't touch it.","Jangan sentuh itu."]]],"tip":["Don't use the tú affirmative form with no: 'No hablas' is a statement (you don't speak); the command is 'No hables'.","Jangan memakai bentuk perintah positif tú dengan no: 'No hablas' adalah pernyataan (kamu tidak bicara); perintahnya 'No hables'."]},{"id":"b1-se","title":["Impersonal se and passive se","Se impersonal dan se pasif"],"what":["Se + 3rd-person verb says what people in general do or what is done, without naming who does it. The verb agrees with the thing: se vende piso (one flat), se venden pisos (several). With people or no noun the verb stays singular.","Se + kata kerja persona ketiga menyatakan apa yang biasa dilakukan orang atau apa yang dikerjakan, tanpa menyebut pelakunya. Kata kerjanya menyesuaikan bendanya: se vende piso (satu apartemen), se venden pisos (beberapa). Dengan orang atau tanpa kata benda, kata kerja tetap tunggal."],"pattern":[{"head":[["Type","Jenis"],["Pattern","Pola"],["Example","Contoh"]],"rows":[[["passive, singular thing","pasif, benda tunggal"],"{se} + verb (sg.) + noun (sg.)","Aquí {se habla} inglés."],[["passive, plural things","pasif, benda jamak"],"{se} + verb (pl.) + noun (pl.)","{Se venden} coches usados."],[["impersonal, no noun","impersonal, tanpa kata benda"],"{se} + verb (sg.)","Aquí {se vive} bien. ¿Cómo {se dice}…?"],[["impersonal, people","impersonal, orang"],"{se} + verb (sg.) + a + person","{Se busca} a dos camareros."],[["accidents (it happened to me)","kejadian tak sengaja"],"{se} + me/te/le + verb","{Se me} olvidó. {Se le} rompieron las gafas."]]}],"examples":[["¿Cómo se dice 'thank you' en español?",["How do you say 'thank you' in Spanish?","Bagaimana mengatakan 'thank you' dalam bahasa Spanyol?"]],["Se alquilan habitaciones.",["Rooms for rent.","Kamar disewakan."]],["Se me ha perdido el móvil.",["I've lost my phone (it got lost on me).","Ponsel saya hilang."]]],"tip":["In the accident pattern the verb agrees with the thing, not the person: se me olvidaron las llaves (the keys), se me olvidó la llave.","Dalam pola kejadian tak sengaja, kata kerjanya menyesuaikan bendanya, bukan orangnya: se me olvidaron las llaves, se me olvidó la llave."]},{"id":"b1-reported","title":["Reported speech","Kalimat tidak langsung"],"what":["When the reporting verb is in the present (dice que), tenses stay the same. When it is in the past (dijo que), tenses usually move back: present → imperfect, preterite/perfect → pluperfect, future → conditional, command → imperfect subjunctive. Pronouns, time and place words change too.","Jika kata kerja pelapornya kala kini (dice que), kala tidak berubah. Jika kala lampau (dijo que), kala biasanya mundur: kini → imperfek, preterit/perfect → pluperfek, depan → kondisional, perintah → subjuntif imperfek. Kata ganti, kata waktu dan tempat juga berubah."],"pattern":[{"head":[["Direct","Langsung"],["Reported (dijo que…)","Tidak langsung (dijo que…)"]],"rows":[["«Estoy cansada.»","Dijo que {estaba} cansada."],["«He terminado.» / «Terminé.»","Dijo que {había terminado}."],["«Vendré mañana.»","Dijo que {vendría} al día siguiente."],["«Voy a llamar.»","Dijo que {iba a} llamar."],["«Llámame.»","Me pidió que la {llamara}."],["«¿Tienes hambre?»","Me preguntó {si} tenía hambre."],["«¿Dónde vives?»","Me preguntó {dónde} vivía."]],"note":["Time words: hoy → aquel día, mañana → al día siguiente, ayer → el día anterior, aquí → allí.","Kata waktu: hoy → aquel día, mañana → al día siguiente, ayer → el día anterior, aquí → allí."]}],"examples":[["Carlos dice que llega tarde.",["Carlos says he's arriving late.","Carlos bilang dia datang terlambat."]],["Me dijo que no podía venir.",["She told me she couldn't come.","Dia bilang kepada saya bahwa dia tidak bisa datang."]],["Le pregunté si quería un café.",["I asked him if he wanted a coffee.","Saya bertanya apakah dia mau kopi."]]],"tip":["Yes/no questions are reported with si; question words keep their accent: me preguntó qué hora era.","Pertanyaan ya/tidak dilaporkan dengan si; kata tanya tetap beraksen: me preguntó qué hora era."]},{"id":"b1-periphrases","title":["Verb phrases: acabar de, volver a, seguir, llevar","Frasa kata kerja: acabar de, volver a, seguir, llevar"],"what":["Spanish uses short verb combinations for meanings that English expresses with adverbs: just done, again, still, for how long, stop doing. Learn the preposition that goes with each one.","Bahasa Spanyol memakai gabungan kata kerja pendek untuk arti yang dalam bahasa Inggris diungkapkan dengan kata keterangan: baru saja, lagi, masih, sudah berapa lama, berhenti. Hafalkan kata depan yang menyertai masing-masing."],"pattern":[{"head":[["Phrase","Frasa"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["{acabar de} + inf.",["have just done","baru saja"],"{Acabo de} llegar."],["{volver a} + inf.",["do again","melakukan lagi"],"No {vuelvas a} hacerlo."],["{dejar de} + inf.",["stop doing","berhenti"],"{He dejado de} fumar."],["{empezar a} / {ponerse a} + inf.",["start doing","mulai"],"{Se puso a} llorar."],["{seguir} + gerund",["still / keep doing","masih / terus"],"{Sigue} lloviendo."],["{llevar} + time + gerund",["have been doing for","sudah … selama"],"{Llevo} dos años estudiando español."],["{deber} + inf. / {tener que} + inf.",["should / have to","sebaiknya / harus"],"{Debes} descansar."]]}],"examples":[["Acabamos de comer.",["We've just eaten.","Kami baru saja makan."]],["¿Sigues viviendo en Madrid?",["Do you still live in Madrid?","Kamu masih tinggal di Madrid?"]],["Llevo una hora esperándote.",["I've been waiting for you for an hour.","Saya sudah menunggumu satu jam."]]],"tip":["'Acabo de comer' (I've just eaten) uses the present, even though the meaning is past. Seguir takes the gerund, never the infinitive: sigue trabajando.","'Acabo de comer' (saya baru saja makan) memakai kala kini meskipun artinya lampau. Seguir diikuti gerundio, bukan infinitif: sigue trabajando."]},{"id":"b1-gustar-type","title":["Verbs like gustar: doler, molestar, parecer…","Kata kerja seperti gustar: doler, molestar, parecer…"],"what":["Many verbs about feelings and reactions work like gustar: the thing or activity is the subject and the person is the indirect object. The verb is singular for one thing or an infinitive, plural for plural things.","Banyak kata kerja tentang perasaan dan reaksi bekerja seperti gustar: benda atau kegiatan menjadi subjek, dan orangnya objek tak langsung. Kata kerja tunggal untuk satu hal atau infinitif, jamak untuk benda jamak."],"pattern":[{"head":[["Verb","Kata kerja"],["Meaning","Arti"],["Example","Contoh"]],"rows":[["doler (ue)",["hurt","sakit"],"Me {duele} la cabeza. Me {duelen} los pies."],["molestar",["bother","mengganggu"],"Le {molesta} el ruido."],["parecer",["seem, think of","tampak, menurut"],"¿Qué te {parece}? Me {parecen} caros."],["interesar",["interest","menarik minat"],"Nos {interesa} la historia."],["importar",["matter, mind","penting, keberatan"],"¿Te {importa} si abro la ventana?"],["faltar / quedar",["be missing / be left","kurang / tersisa"],"Me {faltan} dos euros. Nos {queda} una hora."],["apetecer",["feel like","ingin, berselera"],"¿Te {apetece} un café?"]]}],"examples":[["Me duele la espalda.",["My back hurts.","Punggung saya sakit."]],["¿Te importa esperar un momento?",["Do you mind waiting a moment?","Kamu keberatan menunggu sebentar?"]],["Nos quedan diez minutos.",["We have ten minutes left.","Kita masih punya sepuluh menit."]]],"tip":["Body parts take the article, not a possessive: me duele la cabeza, not 'mi cabeza duele'.","Bagian tubuh memakai artikel, bukan kata kepemilikan: me duele la cabeza, bukan 'mi cabeza duele'."]},{"id":"b1-ser-estar-meaning","title":["Adjectives that change meaning with ser and estar","Kata sifat yang berubah arti dengan ser dan estar"],"what":["Some adjectives mean one thing with ser (a characteristic) and something different with estar (a state or condition). Choosing the wrong verb changes the message, sometimes in an embarrassing way.","Beberapa kata sifat punya satu arti dengan ser (sifat) dan arti lain dengan estar (keadaan atau kondisi). Salah memilih kata kerja mengubah pesannya, kadang dengan cara yang memalukan."],"pattern":[{"head":[["Adjective","Kata sifat"],["with ser","dengan ser"],["with estar","dengan estar"]],"rows":[["listo",["clever","pintar"],["ready","siap"]],["aburrido",["boring","membosankan"],["bored","bosan"]],["malo",["bad (person, thing)","jahat, buruk"],["ill / bad (food)","sakit / busuk (makanan)"]],["rico",["rich","kaya"],["delicious","enak"]],["verde",["green (colour)","hijau (warna)"],["unripe / inexperienced","mentah / belum berpengalaman"]],["vivo",["lively, sharp","lincah, cerdik"],["alive","hidup"]],["orgulloso",["arrogant","sombong"],["proud (of)","bangga"]],["seguro",["safe","aman"],["sure, certain","yakin"]]]}],"examples":[["La película es aburrida.",["The film is boring.","Filmnya membosankan."]],["Estoy aburrido.",["I'm bored.","Saya bosan."]],["¿Estás listo? Nos vamos.",["Are you ready? We're leaving.","Kamu sudah siap? Kita berangkat."]]],"tip":["Food you are eating 'está rica / buena' (tastes good). A person who 'es rico' has money.","Makanan yang sedang dimakan 'está rica / buena' (enak). Orang yang 'es rico' punya banyak uang."]},{"id":"b1-connectors","title":["Connectors: contrast, cause and result","Kata penghubung: kontras, sebab dan akibat"],"what":["Connectors organise ideas. Aunque + indicative states a known fact; aunque + subjunctive concedes something that may or may not be true. Sin embargo and por eso start a new clause or sentence.","Kata penghubung mengatur gagasan. Aunque + indikatif menyatakan fakta yang diketahui; aunque + subjuntif mengakui sesuatu yang mungkin benar atau tidak. Sin embargo dan por eso memulai klausa atau kalimat baru."],"pattern":[{"head":[["Meaning","Arti"],["Connector","Kata penghubung"],["Example","Contoh"]],"rows":[[["contrast","kontras"],"{pero}, {sin embargo}, {aunque}","Es caro; {sin embargo}, lo compro."],[["correction (not X but Y)","koreksi (bukan X tetapi Y)"],"{sino} / {sino que}","No es rojo {sino} naranja."],[["cause","sebab"],"{porque}, {como} (at the start), {ya que}","{Como} llovía, no salimos."],[["result","akibat"],"{por eso}, {así que}, {por lo tanto}","Estaba cansado, {así que} me acosté."],[["concession","konsesi"],"{aunque} + indicative / subjunctive","{Aunque} llueve, salgo. {Aunque} llueva, saldré."],[["addition","tambahan"],"{además}, {también}","Es barato y, {además}, está cerca."]]}],"examples":[["No fui a la fiesta porque estaba enfermo.",["I didn't go to the party because I was ill.","Saya tidak ke pesta karena sakit."]],["No quiero té, sino café.",["I don't want tea, but coffee.","Saya tidak mau teh, melainkan kopi."]],["Aunque haga frío, iremos a la playa.",["Even if it's cold, we'll go to the beach.","Meskipun (mungkin) dingin, kami akan ke pantai."]]],"tip":["Use sino (not pero) after a negative to correct: 'No es médico sino enfermero'. Use como, not porque, at the start of a sentence: 'Como no tenía dinero, no fui'.","Pakai sino (bukan pero) setelah kalimat negatif untuk mengoreksi: 'No es médico sino enfermero'. Pakai como, bukan porque, di awal kalimat: 'Como no tenía dinero, no fui'."]}]}]};
